# Aquarium / Waterfall puzzle solver
# Rules:
# 1. Each region has a consistent water level (water fills from bottom up within region)
# 2. If a cell is water, all cells below it in the same region are also water
# 3. Row clues = exact number of water cells per row
# 4. Column clues = exact number of water cells per column

from itertools import product

def solve(observation):
    region_grid = observation['region']
    row_counts = observation['row_water_counts']
    col_counts = observation['col_water_counts']

    nrows = len(region_grid)
    ncols = len(region_grid[0])

    # Find all unique regions
    regions = {}
    for r in range(nrows):
        for c in range(ncols):
            rid = region_grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # For each region, determine the cells sorted by row (bottom to top)
    # Water level in a region means: all cells at row >= water_level_row are water
    # Actually: water fills from bottom. If water level is k, then rows >= k in that region are water.
    # We represent each region's state as a "water level" = number of rows from bottom that are filled
    # For region with cells at rows r1 < r2 < ... < rn (distinct rows),
    # water level 0 = no water, water level 1 = bottom row filled, etc.

    # For each region, get the distinct rows it occupies, sorted
    region_rows = {}
    region_cells_by_row = {}
    for rid, cells in regions.items():
        rows_in_region = sorted(set(r for r, c in cells))
        region_rows[rid] = rows_in_region
        rdict = {}
        for r, c in cells:
            if r not in rdict:
                rdict[r] = []
            rdict[r].append(c)
        region_cells_by_row[rid] = rdict

    # Water level for region: 0 to len(distinct_rows)
    # level k means bottom k distinct rows are filled with water
    # For level k, the filled rows are region_rows[rid][-k:] (last k rows)

    region_ids = list(regions.keys())
    num_regions = len(region_ids)

    # Precompute for each region and each level, which cells are water
    # region_water_cells[rid][level] = set of (r,c) that are water
    region_water_cells = {}
    for rid in region_ids:
        rows = region_rows[rid]
        n = len(rows)
        levels = []
        for level in range(n + 1):
            water_cells = set()
            if level > 0:
                filled_rows = rows[n - level:]  # bottom 'level' rows
                for row in filled_rows:
                    for c in region_cells_by_row[rid][row]:
                        water_cells.add((row, c))
            levels.append(water_cells)
        region_water_cells[rid] = levels

    # Build a grid contribution: for each region and level, contribution to row/col counts
    # region_row_contrib[rid][level][row] = number of water cells in that row
    # region_col_contrib[rid][level][col] = number of water cells in that col

    region_row_contrib = {}
    region_col_contrib = {}
    for rid in region_ids:
        rows = region_rows[rid]
        n = len(rows)
        row_contribs = []
        col_contribs = []
        for level in range(n + 1):
            rc = {}
            cc = {}
            for (r, c) in region_water_cells[rid][level]:
                rc[r] = rc.get(r, 0) + 1
                cc[c] = cc.get(c, 0) + 1
            row_contribs.append(rc)
            col_contribs.append(cc)
        region_row_contrib[rid] = row_contribs
        region_col_contrib[rid] = col_contribs

    # Now we need to assign a level to each region such that:
    # sum of row contributions = row_counts[r] for each r
    # sum of col contributions = col_counts[c] for each c

    # Use backtracking with constraint propagation
    # Order regions by most constrained first (fewest valid levels)

    # Current row/col sums
    current_row = [0] * nrows
    current_col = [0] * ncols

    # Max possible contribution from unassigned regions
    # For pruning: current + max_remaining >= required, current + min_remaining <= required

    # Precompute max/min row/col contribution per region across all levels
    region_max_row = {}
    region_min_row = {}
    region_max_col = {}
    region_min_col = {}

    for rid in region_ids:
        n = len(region_rows[rid])
        max_r = {}
        min_r = {}
        max_c = {}
        min_c = {}
        for level in range(n + 1):
            for r, v in region_row_contrib[rid][level].items():
                max_r[r] = max(max_r.get(r, 0), v)
                min_r[r] = min(min_r.get(r, float('inf')), v)
            for c, v in region_col_contrib[rid][level].items():
                max_c[c] = max(max_c.get(c, 0), v)
                min_c[c] = min(min_c.get(c, float('inf')), v)
        # For rows/cols not appearing in any level, min=0, max=0
        region_max_row[rid] = max_r
        region_min_row[rid] = {r: min_r.get(r, 0) for r in range(nrows)}
        region_max_col[rid] = max_c
        region_min_col[rid] = {c: min_c.get(c, 0) for c in range(ncols)}

    # Precompute total max/min for all regions
    total_max_row = [0] * nrows
    total_min_row = [0] * nrows
    total_max_col = [0] * ncols
    total_min_col = [0] * ncols

    for rid in region_ids:
        for r in range(nrows):
            total_max_row[r] += region_max_row[rid].get(r, 0)
            total_min_row[r] += region_min_row[rid].get(r, 0)
        for c in range(ncols):
            total_max_col[c] += region_max_col[rid].get(c, 0)
            total_min_col[c] += region_min_col[rid].get(c, 0)

    # Remaining max/min (subtract assigned regions as we go)
    remaining_max_row = list(total_max_row)
    remaining_min_row = list(total_min_row)
    remaining_max_col = list(total_max_col)
    remaining_min_col = list(total_min_col)

    assignment = {}

    def is_feasible():
        for r in range(nrows):
            needed = row_counts[r]
            if current_row[r] + remaining_max_row[r] < needed:
                return False
            if current_row[r] + remaining_min_row[r] > needed:
                return False
        for c in range(ncols):
            needed = col_counts[c]
            if current_col[c] + remaining_max_col[c] < needed:
                return False
            if current_col[c] + remaining_min_col[c] > needed:
                return False
        return True

    def backtrack(idx):
        if idx == num_regions:
            # Check exact match
            for r in range(nrows):
                if current_row[r] != row_counts[r]:
                    return False
            for c in range(ncols):
                if current_col[c] != col_counts[c]:
                    return False
            return True

        rid = region_ids[idx]
        n = len(region_rows[rid])

        # Remove this region's contribution from remaining
        for r in range(nrows):
            remaining_max_row[r] -= region_max_row[rid].get(r, 0)
            remaining_min_row[r] -= region_min_row[rid].get(r, 0)
        for c in range(ncols):
            remaining_max_col[c] -= region_max_col[rid].get(c, 0)
            remaining_min_col[c] -= region_min_col[rid].get(c, 0)

        for level in range(n + 1):
            # Apply this level
            rc = region_row_contrib[rid][level]
            cc = region_col_contrib[rid][level]

            # Check immediate feasibility
            valid = True
            for r, v in rc.items():
                if current_row[r] + v > row_counts[r]:
                    valid = False
                    break
            if valid:
                for c, v in cc.items():
                    if current_col[c] + v > col_counts[c]:
                        valid = False
                        break

            if not valid:
                continue

            # Apply
            for r, v in rc.items():
                current_row[r] += v
            for c, v in cc.items():
                current_col[c] += v

            assignment[rid] = level

            if is_feasible():
                if backtrack(idx + 1):
                    # Restore remaining before returning
                    for r in range(nrows):
                        remaining_max_row[r] += region_max_row[rid].get(r, 0)
                        remaining_min_row[r] += region_min_row[rid].get(r, 0)
                    for c in range(ncols):
                        remaining_max_col[c] += region_max_col[rid].get(c, 0)
                        remaining_min_col[c] += region_min_col[rid].get(c, 0)
                    return True

            # Undo
            for r, v in rc.items():
                current_row[r] -= v
            for c, v in cc.items():
                current_col[c] -= v

        # Restore remaining
        for r in range(nrows):
            remaining_max_row[r] += region_max_row[rid].get(r, 0)
            remaining_min_row[r] += region_min_row[rid].get(r, 0)
        for c in range(ncols):
            remaining_max_col[c] += region_max_col[rid].get(c, 0)
            remaining_min_col[c] += region_min_col[rid].get(c, 0)

        return False

    # Sort regions by number of valid levels (most constrained first)
    # Simple heuristic: fewer levels = more constrained
    region_ids.sort(key=lambda rid: len(region_rows[rid]))

    if backtrack(0):
        # Build solution grid
        grid = [[None] * ncols for _ in range(nrows)]
        for rid, level in assignment.items():
            for (r, c) in region_water_cells[rid][level]:
                grid[r][c] = 'W'
        return grid
    else:
        return "No Solution"

