        key = f'({float(r)},{c+0.5})'
        return horizontal.get(key, None)

    def get_v_constraint(r, c):
        # constraint between (r,c) and (r+1,c)
        key = f'({r+0.5},{float(c)})'
        return vertical.get(key, None)

    def is_valid_partial(grid, r, c, val):
        # Check no three consecutive in row
        row = grid[r]
        # Check left two
        if c >= 2 and row[c-1] == val and row[c-2] == val:
            return False
        # Check right two (if already filled)
        if c <= n-3 and row[c+1] == val and row[c+2] == val:
            return False
        # Check left one and right one
        if c >= 1 and c <= n-2 and row[c-1] == val and row[c+1] == val:
            return False

        # Check no three consecutive in col
        col_vals = [grid[i][c] for i in range(n)]
        if r >= 2 and col_vals[r-1] == val and col_vals[r-2] == val:
            return False
        if r <= n-3 and col_vals[r+1] == val and col_vals[r+2] == val:
            return False
        if r >= 1 and r <= n-2 and col_vals[r-1] == val and col_vals[r+1] == val:
            return False

        # Check horizontal constraints
        # Between (r, c-1) and (r, c)
        if c > 0 and grid[r][c-1] is not None:
            con = get_h_constraint(r, c-1)
            if con == '=' and grid[r][c-1] != val:
