            return None

        r, c, possible = best
        for val in possible:
            grid[r][c] = val
            grid_copy = deepcopy(grid)
            if propagate(grid_copy):
                result = backtrack(grid_copy)
                if result is not None:
                    return result
            grid[r][c] = None

        return None

    # Initial propagation
    if not propagate(grid):
        return "No Solution"

    result = backtrack(grid)

    if result is None:
        return "No Solution"

    return result

