            return None

        result = find_next_empty(g)
        if result is None:
            return None

        if len(result) == 3:
            r, c, options = result
        else:
            return None

        if not options:
            return None

        for val in options:
            new_g = copy.deepcopy(g)
            new_g[r][c] = val
            result = backtrack(new_g)
            if result is not None:
                return result

        return None

    solution = backtrack(grid)

    if solution is None:
        return "No Solution"

    return solution


