    def select_unassigned(domains):
        """MRV heuristic: select cell with minimum remaining values."""
        min_size = 3
        best = None
        for r in range(N):
            for c in range(N):
                size = len(domains[r][c])
                if size > 1 and size < min_size:
                    min_size = size
                    best = (r, c)
                    if min_size == 2:
                        return best
        return best

    def backtrack(domains):
