                    domains[r1][c1] = new_d1
                    changed = True
                if new_d2 != d2:
                    domains[r2][c2] = new_d2
                    changed = True
        return True

    def apply_alldiff_pruning(domains):
        """If a cell has a singleton domain, remove that value from row/col."""
        changed = True
        while changed:
