                    if len(domains[r][c]) == 1:
                        val = next(iter(domains[r][c]))
                        # Remove from same row
                        for c2 in range(N):
                            if c2 != c and val in domains[r][c2]:
                                domains[r][c2].discard(val)
                                if not domains[r][c2]:
                                    return False
                                changed = True
                        # Remove from same col
                        for r2 in range(N):
                            if r2 != r and val in domains[r2][c]:
                                domains[r2][c].discard(val)
                                if not domains[r2][c]:
                                    return False
                                changed = True
        return True

    def propagate(domains):
