        return True

    def copy_domains(domains):
        return [[ s.copy() for s in row] for row in domains]

    def select_unassigned(domains):
        """MRV heuristic: select cell with smallest domain > 1."""
        min_size = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                sz = len(domains[r][c])
                if sz > 1 and sz < min_size:
                    min_size = sz
                    best = (r, c)
        return best

    def backtrack(domains):
        # Check if solved
        cell = select_unassigned(domains)
        if cell is None:
            # All assigned - verify
            return domains

        r, c = cell
        for val in sorted(domains[r][c]):
            new_domains = copy_domains(domains)
            new_domains[r][c] = {val}
            ok = propagate(new_domains)
            if ok:
                result = backtrack(new_domains)
                if result is not None:
                    return result
        return None

    # Initial propagation
    ok = propagate(domains)
    if not ok:
        return "No Solution"

    result = backtrack(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(next(iter(result[r][c])))
        grid.append(row)

    return grid

