                neighbors.append(('gt', r, c+1))  # self > neighbor
        # vertical
        if r > 0 and (r-1, c) in v_constraints:
            sym = v_constraints[(r-1, c)]
            if sym == 'v':  # grid[r-1][c] > grid[r][c]
                neighbors.append(('lt', r-1, c))  # self < neighbor
            else:  # grid[r-1][c] < grid[r][c]
                neighbors.append(('gt', r-1, c))  # self > neighbor
        if r < N-1 and (r, c) in v_constraints:
            sym = v_constraints[(r, c)]
            if sym == 'v':  # grid[r][c] > grid[r+1][c]
                neighbors.append(('gt', r+1, c))  # self > neighbor
            else:  # grid[r][c] < grid[r+1][c]
                neighbors.append(('lt', r+1, c))  # self < neighbor
        return neighbors

    def check_constraints(grid):
        """Check all constraints are satisfied"""
        for (r, c), sym in h_constraints.items():
            if grid[r][c] is not None and grid[r][c+1] is not None:
                if sym == '<' and not (grid[r][c] < grid[r][c+1]):
                    return False
                if sym == '>' and not (grid[r][c] > grid[r][c+1]):
                    return False
        for (r, c), sym in v_constraints.items():
            if grid[r][c] is not None and grid[r+1][c] is not None:
                if sym == 'v' and not (grid[r][c] > grid[r+1][c]):
                    return False
                if sym == '^' and not (grid[r][c] < grid[r+1][c]):
                    return False
        return True

    def is_valid_placement(grid, r, c, val):
        """Check if placing val at (r,c) is valid"""
        # Check row
        for cc in range(N):
            if cc != c and grid[r][cc] == val:
                return False
        # Check col
        for rr in range(N):
            if rr != r and grid[rr][c] == val:
                return False
        # Check horizontal constraints
        if c > 0 and (r, c-1) in h_constraints:
            sym = h_constraints[(r, c-1)]
            left = grid[r][c-1]
            if left is not None:
                if sym == '<' and not (left < val):
                    return False
                if sym == '>' and not (left > val):
                    return False
        if c < N-1 and (r, c) in h_constraints:
            sym = h_constraints[(r, c)]
            right = grid[r][c+1]
            if right is not None:
                if sym == '<' and not (val < right):
                    return False
                if sym == '>' and not (val > right):
                    return False
        # Check vertical constraints
        if r > 0 and (r-1, c) in v_constraints:
            sym = v_constraints[(r-1, c)]
            top = grid[r-1][c]
            if top is not None:
                if sym == 'v' and not (top > val):
                    return False
                if sym == '^' and not (top < val):
                    return False
        if r < N-1 and (r, c) in v_constraints:
            sym = v_constraints[(r, c)]
            bottom = grid[r+1][c]
            if bottom is not None:
                if sym == 'v' and not (val > bottom):
                    return False
                if sym == '^' and not (val < bottom):
                    return False
        return True

    def compute_possible(grid):
        """Compute possible values for each cell"""
        poss = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if grid[r][c] is not None:
                    poss[r][c] = {grid[r][c]}
