        while queue:
            r, c = queue.pop(0)

            if grid[r][c] is not None:
                val = grid[r][c]
                # Remove from row
                for cc in range(N):
                    if cc != c and val in poss[r][cc]:
                        poss[r][cc].discard(val)
                        if len(poss[r][cc]) == 0:
                            return False
                        if len(poss[r][cc]) == 1 and grid[r][cc] is None:
                            v = next(iter(poss[r][cc]))
                            grid[r][cc] = v
                            queue.append((r, cc))
                # Remove from col
                for rr in range(N):
                    if rr != r and val in poss[rr][c]:
                        poss[rr][c].discard(val)
                        if len(poss[rr][c]) == 0:
                            return False
                        if len(poss[rr][c]) == 1 and grid[rr][c] is None:
                            v = next(iter(poss[rr][c]))
                            grid[rr][c] = v
                            queue.append((rr, c))

