                # Horizontal left
                if c > 0 and (r, c-1) in h_constraints:
                    sym = h_constraints[(r, c-1)]
                    left_poss = poss[r][c-1] if grid[r][c-1] is None else {grid[r][c-1]}
                    if sym == '<':  # left < self
                        min_left = min(left_poss)
                        # self > min_left, so self >= min_left + 1
