                        new_poss = {v for v in poss[r][c] if v < max_top}
                        if new_poss != poss[r][c]:
                            poss[r][c] = new_poss
                            if len(poss[r][c]) == 0:
                                return False
                            if len(poss[r][c]) == 1 and grid[r][c] is None:
                                grid[r][c] = next(iter(poss[r][c]))
                                queue.append((r, c))
                    else:  # top < self
                        min_top = min(top_poss)
                        new_poss = {v for v in poss[r][c] if v > min_top}
                        if new_poss != poss[r][c]:
                            poss[r][c] = new_poss
                            if len(poss[r][c]) == 0:
                                return False
                            if len(poss[r][c]) == 1 and grid[r][c] is None:
                                grid[r][c] = next(iter(poss[r][c]))
                                queue.append((r, c))

                # Vertical down
                if r < N-1 and (r, c) in v_constraints:
                    sym = v_constraints[(r, c)]
                    bot_poss = poss[r+1][c] if grid[r+1][c] is None else {grid[r+1][c]}
                    if sym == 'v':  # self > bottom
                        min_bot = min(bot_poss)
                        new_poss = {v for v in poss[r][c] if v > min_bot}
                        if new_poss != poss[r][c]:
                            poss[r][c] = new_poss
                            if len(poss[r][c]) == 0:
                                return False
                            if len(poss[r][c]) == 1 and grid[r][c] is None:
                                grid[r][c] = next(iter(poss[r][c]))
                                queue.append((r, c))
                    else:  # self < bottom
                        max_bot = max(bot_poss)
                        new_poss = {v for v in poss[r][c] if v < max_bot}
                        if new_poss != poss[r][c]:
                            poss[r][c] = new_poss
                            if len(poss[r][c]) == 0:
                                return False
                            if len(poss[r][c]) == 1 and grid[r][c] is None:
                                grid[r][c] = next(iter(poss[r][c]))
                                queue.append((r, c))

        return True

    def backtrack(grid, poss):
        # Find unassigned cell with minimum remaining values (MRV heuristic)
        min_poss = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    if len(poss[r][c]) < min_poss:
                        min_poss = len(poss[r][c])
                        best = (r, c)
                        if min_poss == 1:
                            break
            if min_poss == 1:
                break

        if best is None:
            # All cells filled, verify
            return check_constraints(grid)

        r, c = best

        for val in sorted(poss[r][c]):
            if is_valid_placement(grid, r, c, val):
                # Save state
                grid_copy = [row[:] for row in grid]
                poss_copy = [row[:] for row in poss]
                for rr in range(N):
                    poss_copy[rr] = [s.copy() for s in poss[rr]]

                grid[r][c] = val
                poss[r][c] = {val}

                if propagate(grid, poss, [(r, c)]):
                    if backtrack(grid, poss):
                        return True

                # Restore state
                for rr in range(N):
                    grid[rr] = grid_copy[rr][:]
                    poss[rr] = [s.copy() for s in poss_copy[rr]]

        return False

    # Initialize grid from data
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]

    # Compute initial possible values
    poss = compute_possible(grid)

    # Initial propagation
    if not propagate(grid, poss):
        return "No Solution"

    # Backtrack search
    if backtrack(grid, poss):
        return grid

    return "No Solution"


