# Hashiwokakero (Bridges) Solver
# Human-like solving with constraint propagation + backtracking

from collections import defaultdict, deque
import copy

def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows > 0 else 0

    # Extract islands
    islands = {}
    for r in range(rows):
