        island_list = sorted(islands_set)

        for (r, c) in island_list:
            # Right
            for cc in range(c+1, cols):
                if (r, cc) in islands_set:
                    neighbors[(r,c)].append((r, cc))
                    break
                elif data[r][cc] is not None:
                    break
            # Left
            for cc in range(c-1, -1, -1):
                if (r, cc) in islands_set:
                    neighbors[(r,c)].append((r, cc))
                    break
                elif data[r][cc] is not None:
                    break
            # Down
            for rr in range(r+1, rows):
                if (rr, c) in islands_set:
                    neighbors[(r,c)].append((rr, c))
                    break
                elif data[rr][c] is not None:
                    break
            # Up
            for rr in range(r-1, -1, -1):
                if (rr, c) in islands_set:
                    neighbors[(r,c)].append((rr, c))
                    break
                elif data[rr][c] is not None:
                    break

        return neighbors

    neighbors = get_neighbors(set(islands.keys()), rows, cols)

    # Canonical edge key
    def edge_key(a, b):
        return (min(a,b), max(a,b))

    # Check if bridge between a and b would cross any existing bridge
    def bridges_cross(a, b, bridges):
        r1, c1 = a
        r2, c2 = b
        # a-b is either horizontal or vertical
        for (p, q), cnt in bridges.items():
            if cnt == 0:
                continue
            r3, c3 = p
            r4, c4 = q
            # Check crossing: one horizontal, one vertical
            if r1 == r2 and r3 != r4:  # a-b horizontal, p-q vertical
                min_c = min(c1, c2)
                max_c = max(c1, c2)
                min_r = min(r3, r4)
                max_r = max(r3, r4)
                if min_r < r1 < max_r and min_c < c3 < max_c:
                    return True
            elif c1 == c2 and c3 == c4:  # both vertical, no cross
                pass
            elif c1 == c2 and r3 == r4:  # a-b vertical, p-q horizontal
                min_r = min(r1, r2)
                max_r = max(r1, r2)
                min_c = min(c3, c4)
                max_c = max(c3, c4)
                if min_c < c1 < max_c and min_r < r3 < max_r:
                    return True
        return False

    # Check if bridge passes through any island
    def bridge_through_island(a, b, islands_set):
        r1, c1 = a
        r2, c2 = b
        if r1 == r2:
            for cc in range(min(c1,c2)+1, max(c1,c2)):
                if (r1, cc) in islands_set:
                    return True
        else:
            for rr in range(min(r1,r2)+1, max(r1,r2)):
                if (rr, c1) in islands_set:
                    return True
        return False

    # Get valid neighbors considering current bridges (no crossing, no through-island)
    def get_valid_neighbors_for_edge(a, b, bridges, islands_set):
        if bridge_through_island(a, b, islands_set):
            return False
        if bridges_cross(a, b, bridges):
            return False
        return True

    # Compute remaining capacity for each island
    def remaining(island, bridges, island_req):
        used = 0
        for nb in neighbors[island]:
            k = edge_key(island, nb)
            used += bridges.get(k, 0)
        return island_req[island] - used

    # Compute max possible bridges for an edge (considering crossing constraints)
    def max_bridges_for_edge(a, b, bridges, island_req, islands_set):
        if bridge_through_island(a, b, islands_set):
            return 0
        if bridges_cross(a, b, bridges):
            return 0
        rem_a = remaining(a, bridges, island_req)
        rem_b = remaining(b, bridges, island_req)
        current = bridges.get(edge_key(a,b), 0)
        return min(2, current + min(rem_a, rem_b))

    # Connectivity check using union-find
    def is_connected(bridges, islands_set):
        parent = {i: i for i in islands_set}
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

