    def is_feasible(bridges, island_req, islands_set):
        # Check no island exceeded
        for isl in islands_set:
            rem = remaining(isl, bridges, island_req)
            if rem < 0:
                return False

        # Check each island can still reach its requirement
        for isl in islands_set:
            rem = remaining(isl, bridges, island_req)
            if rem == 0:
                continue
            # Max bridges still possible from this island
            max_possible = 0
            for nb in neighbors[isl]:
                k = edge_key(isl, nb)
                current = bridges.get(k, 0)
                max_add = max_bridges_for_edge(isl, nb, bridges, island_req, islands_set) - current
                max_possible += max_add
            if max_possible < rem:
                return False

        return True

    # Check if solution is complete
    def is_complete(bridges, island_req, islands_set):
        for isl in islands_set:
            if remaining(isl, bridges, island_req) != 0:
                return False
        return is_connected(bridges, islands_set)

    # Human-like deduction: forced bridges
    def deduce(bridges, island_req, islands_set):
        changed = True
        while changed:
            changed = False

            for isl in list(islands_set):
                rem = remaining(isl, bridges, island_req)
                if rem < 0:
                    return False  # infeasible

                # Get valid neighbors and their max additional bridges
                valid_nbs = []
                total_max = 0
                for nb in neighbors[isl]:
                    k = edge_key(isl, nb)
                    current = bridges.get(k, 0)
                    mx = max_bridges_for_edge(isl, nb, bridges, island_req, islands_set)
                    add = mx - current
                    if add > 0:
                        valid_nbs.append((nb, add, current, mx))
                        total_max += add

                if rem == 0:
                    # All neighbors must have no more bridges
                    continue

                if total_max < rem:
                    return False  # infeasible

                # If total_max == rem, all valid edges must be maxed out
                if total_max == rem:
                    for nb, add, current, mx in valid_nbs:
                        k = edge_key(isl, nb)
                        if bridges.get(k, 0) < mx:
                            bridges[k] = mx
                            changed = True

                # If only one neighbor can take bridges and rem > 0
                if len(valid_nbs) == 1 and rem > 0:
                    nb, add, current, mx = valid_nbs[0]
                    k = edge_key(isl, nb)
                    needed = rem
                    if needed <= mx - current:
                        bridges[k] = current + needed
                        changed = True

                # Forced minimum: if removing one neighbor still can't satisfy
                for i, (nb, add, current, mx) in enumerate(valid_nbs):
                    other_max = total_max - add
                    if other_max < rem:
                        # Must use at least (rem - other_max) on this edge
                        forced = rem - other_max
                        k = edge_key(isl, nb)
                        if bridges.get(k, 0) < current + forced:
                            bridges[k] = current + forced
                            changed = True

        return True

    # Get all edges with their possible values
    def get_edges(islands_set):
        edges = set()
        for isl in islands_set:
            for nb in neighbors[isl]:
                edges.add(edge_key(isl, nb))
        return list(edges)

    # Main backtracking solver
    def backtrack(bridges, island_req, islands_set):
        # Apply deduction
        bridges_copy = dict(bridges)
        if not deduce(bridges_copy, island_req, islands_set):
            return None

        if not is_feasible(bridges_copy, island_req, islands_set):
            return None

        if is_complete(bridges_copy, island_req, islands_set):
            return bridges_copy

        # Find the most constrained edge to branch on
        # Pick island with smallest remaining > 0 and fewest valid neighbors
        best_edge = None
        best_score = float('inf')

        for isl in islands_set:
            rem = remaining(isl, bridges_copy, island_req)
            if rem <= 0:
                continue
            valid_nbs = []
            for nb in neighbors[isl]:
                k = edge_key(isl, nb)
                current = bridges_copy.get(k, 0)
                mx = max_bridges_for_edge(isl, nb, bridges_copy, island_req, islands_set)
                if mx > current:
                    valid_nbs.append((nb, current, mx))

            if not valid_nbs:
                return None

            score = len(valid_nbs)
            if score < best_score:
                best_score = score
                # Pick first valid edge from this island
                nb, current, mx = valid_nbs[0]
                best_edge = (edge_key(isl, nb), current, mx)

        if best_edge is None:
            return None

        k, current, mx = best_edge

        # Try values from current+1 to mx
        for val in range(current + 1, mx + 1):
            new_bridges = dict(bridges_copy)
            new_bridges[k] = val
            result = backtrack(new_bridges, island_req, islands_set)
            if result is not None:
                return result

        return None

    # Initialize bridges
    initial_bridges = {}
    all_edges = get_edges(set(islands.keys()))
    for e in all_edges:
        initial_bridges[e] = 0

    result = backtrack(initial_bridges, dict(islands), set(islands.keys()))

    if result is None:
        return "No Solution"

    # Format output
    answer = {}
    for (a, b), cnt in result.items():
        if cnt > 0:
            answer[(a, b)] = cnt

    return answer


