        best = None
        best_score = -1

        for r in range(N):
            for c in range(N):
                if state[r][c] == 0:
                    # Score based on how many duplicates this cell has in row/col
                    v = grid[r][c]
                    score = 0
                    for cc in range(N):
                        if cc != c and grid[r][cc] == v:
                            score += 1
                    for rr in range(N):
                        if rr != r and grid[rr][c] == v:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best = (r, c)

