            return None

        r, c = cell

        # Try white first (usually more constrained)
        for val in [1, 2]:  # 1=white, 2=black
            new_state = copy_state(state)
            new_state[r][c] = val
            result = solve_recursive(new_state)
            if result is not None:
                return result

        return None

    # Initial propagation
    initial_state = [[0]*N for _ in range(N)]

    # Apply initial Hitori-like deductions
    # If a value appears only once in a row AND only once in a column, it must be white
    # (Actually this isn't necessarily true, but we can use stronger initial deductions)

    result = solve_recursive(initial_state)

