    # For col j: sum of row_weight[i] for black cells == col_sum[j]

    # Precompute for each row: which subsets of columns sum to row_sum[i]
    # Use bitmask representation for efficiency

    # For each row, find all valid column bitmasks
    row_valid_masks = []
    for i in range(nrows):
