    # Since row_weight is same for all cols, achievable_sums[i] = set of subset sums of row_weight[i..nrows-1]

    achievable_from = []  # achievable_from[i] = set of subset sums of row_weight[i..nrows-1]
    for i in range(nrows + 1):
        weights = row_weight[i:]
        sums = {0}
        for w in weights:
            sums = sums | {s + w for s in sums}
        achievable_from.append(sums)

