# Nurikabe-like puzzle solver (Hitori/Nurikabe variant with visibility rules)
# Rules:
# 1. Each clue counts white cells visible from it (orthogonally, including itself)
# 2. Visibility blocked by black cells or border
# 3. Clue cells always white
# 4. All white cells form one connected group
# 5. Black cells cannot touch orthogonally

import sys
from collections import deque

def solve(observation):
    data = observation['data']
    N = len(data)

    # Extract clue positions
    clues = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    # State: grid of True (white) / False (black)
    # Clue cells must be white

    def compute_visibility(grid, r, c):
        """Count white cells visible from (r,c) including itself."""
        if not grid[r][c]:
            return 0
        count = 1
        # Up
        for dr in range(r-1, -1, -1):
            if grid[dr][c]:
                count += 1
            else:
                break
        # Down
        for dr in range(r+1, N):
            if grid[dr][c]:
                count += 1
            else:
                break
        # Left
        for dc in range(c-1, -1, -1):
            if grid[r][dc]:
                count += 1
            else:
                break
        # Right
        for dc in range(c+1, N):
            if grid[r][dc]:
                count += 1
            else:
                break
        return count

    def check_no_adjacent_black(grid):
        """Check black cells don't touch orthogonally."""
        for r in range(N):
            for c in range(N):
                if not grid[r][c]:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < N and 0 <= nc < N and not grid[nr][nc]:
                            return False
        return True

    def check_white_connected(grid):
        """Check all white cells are connected."""
        whites = [(r,c) for r in range(N) for c in range(N) if grid[r][c]]
        if not whites:
            return False
        visited = set()
        queue = deque([whites[0]])
        visited.add(whites[0])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N and grid[nr][nc] and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))
        return len(visited) == len(whites)

    def check_clues(grid):
        """Check all clue cells have correct visibility."""
        for (r, c), val in clues.items():
            if compute_visibility(grid, r, c) != val:
                return False
        return True

    def is_valid_solution(grid):
        return (check_clues(grid) and 
                check_no_adjacent_black(grid) and 
                check_white_connected(grid))

    # Get cells that can potentially be black (non-clue cells)
    non_clue_cells = [(r, c) for r in range(N) for c in range(N) 
                      if (r, c) not in clues]

    # Initial grid: all white
    initial_grid = [[True]*N for _ in range(N)]

    # Pruning helpers
    def can_still_satisfy_clues(grid, fixed_black):
        """
        Check if clues can still be satisfied given current state.
        For each clue, compute min and max possible visibility.
        """
        for (r, c), val in clues.items():
            # Current visibility (treating undecided as white)
            current_vis = compute_visibility(grid, r, c)
            if current_vis < val:
                # Can't increase visibility by making cells white (already all white in undecided)
                # Actually current_vis counts all white cells, undecided are white
                # If current_vis < val, impossible
                return False
            # Min visibility: make all undecided cells in line of sight black
            # This is complex; use simpler check: current must be >= val
            # and we need to check if we can reduce to exactly val
        return True

    def check_no_adj_black_partial(grid, r, c):
        """Check that setting (r,c) to black doesn't create adjacent black pair."""
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N and not grid[nr][nc]:
                return False
        return True

