            result = backtrack(new_bulbs, new_no_bulb)
            if result is not None:
                return result

        return None

    result = backtrack(set(), set())

    if result is None:
        return "No Solution"

    # Build answer grid
    answer = [[None]*N for _ in range(N)]
    for (r, c) in result:
        answer[r][c] = 'B'

