    def choose_next(assignment):
        """Choose next unassigned cell using MRV heuristic"""
        # Prefer cells adjacent to numbered black cells
        # Also prefer cells that are the only way to light some cell

        unassigned = [c for c in white_cells if c not in assignment]
        if not unassigned:
            return None

        # Score each unassigned cell
        best = None
        best_score = -1

        bulbs = {pos for pos, val in assignment.items() if val == True}
        lit = set(bulbs)
        for br, bc in bulbs:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = br+dr, bc+dc
                while 0 <= nr < N and (nr, nc) not in black_set:
                    lit.add((nr, nc))
                    nr += dr
                    nc += dc

        # Find cells with fewest options to be lit
        for cell in unassigned:
            if cell in lit:
                continue
            wr, wcc = cell
            can_light_count = 1  # cell itself
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = wr+dr, wcc+dc
                while 0 <= nr < N and (nr, nc) not in black_set:
                    if (nr, nc) not in assignment:
                        can_light_count += 1
                    nr += dr
                    nc += dc
            if best is None or can_light_count < best_score:
                best_score = can_light_count
                best = cell

        if best is not None:
            return best

        # All unlit cells are already lit, just pick first unassigned
        return unassigned[0]

    def backtrack(assignment):
        # Apply propagation first
        assignment = propagate(assignment, list(assignment.keys()))
        if assignment is None:
            return None

        if len(assignment) == len(white_cells):
            if is_complete(assignment):
                return assignment
            return None

        cell = choose_next(assignment)
        if cell is None:
            if is_complete(assignment):
                return assignment
            return None

        # Try placing a bulb first (often more constrained)
        for val in [True, False]:
            new_assignment = dict(assignment)
            new_assignment[cell] = val
            result = backtrack(new_assignment)
            if result is not None:
                return result

        return None

    # Initial propagation with empty assignment
    initial = {}

    # Force cells adjacent to 0-constraint black cells to not be bulbs
    for (r, c), constraint in black_cells.items():
        if constraint == 0:
            for n in get_neighbors(r, c):
                initial[n] = False

    result = backtrack(initial)

    if result is None:
        return "No Solution"

    # Build output grid
    output = [[None] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if (r, c) in white_cells:
                if result.get((r, c)) == True:
                    output[r][c] = 'B'
                else:
                    output[r][c] = None
            # Black cells remain None in output

    return output


