                            set_edge(r, c, nr, nc, False, edge_state)

    # For W cells: must go straight, so need two opposite neighbors
    for r in range(N):
        for c in range(N):
            if data[r][c] == 'W':
                # Check which axes are possible
                h_ok = in_bounds(r, c-1) and in_bounds(r, c+1)
                v_ok = in_bounds(r-1, c) and in_bounds(r+1, c)
                if not h_ok and not v_ok:
                    return "No Solution"
                if not h_ok:
                    # Must be vertical
                    set_edge(r, c, r, c-1, False, edge_state) if in_bounds(r, c-1) else None
                    set_edge(r, c, r, c+1, False, edge_state) if in_bounds(r, c+1) else None
                    set_edge(r, c, r-1, c, True, edge_state)
                    set_edge(r, c, r+1, c, True, edge_state)
                if not v_ok:
                    # Must be horizontal
                    set_edge(r, c, r-1, c, False, edge_state) if in_bounds(r-1, c) else None
                    set_edge(r, c, r+1, c, False, edge_state) if in_bounds(r+1, c) else None
                    set_edge(r, c, r, c-1, True, edge_state)
                    set_edge(r, c, r, c+1, True, edge_state)

    if not propagate(edge_state):
        return "No Solution"

    # Backtracking search
    def backtrack(edge_dict, depth=0):
        if not propagate(edge_dict):
            return None

        unk = [(e, v) for e, v in edge_dict.items() if v is None]

        if not unk:
            # Check validity
            if is_single_loop(edge_dict) and check_white_turn_constraint(edge_dict):
                return edge_dict
            return None

        # Choose edge to branch on - prefer edges near clue cells
        # Heuristic: pick edge adjacent to a clue cell
        best_edge = None
        best_score = -1

        for e, _ in unk:
            (r1,c1),(r2,c2) = e
            score = 0
            if data[r1][c1] is not None:
                score += 2
            if data[r2][c2] is not None:
                score += 2
            # Prefer cells with more constraints
            on1, _, unk1 = get_cell_edges(r1, c1, edge_dict)
            on2, _, unk2 = get_cell_edges(r2, c2, edge_dict)
            score += (2 - len(unk1)) + (2 - len(unk2))
            if score > best_score:
                best_score = score
                best_edge = e

        if best_edge is None:
            best_edge = unk[0][0]

        # Try True first
        for val in [True, False]:
            new_dict = copy_edges(edge_dict)
            (r1,c1),(r2,c2) = best_edge
            if not set_edge(r1, c1, r2, c2, val, new_dict):
                continue
            result = backtrack(new_dict, depth+1)
            if result is not None:
                return result

        return None

    result = backtrack(edge_state)

    if result is None:
        return "No Solution"

    loop = extract_loop(result)
    if loop is None:
        return "No Solution"

    return str(loop)


