        """Set edge at (r,c) direction d to val. Also set symmetric edge. Returns False if contradiction."""
        if edges_state[r][c][d] is not None:
            return edges_state[r][c][d] == val
        edges_state[r][c][d] = val
        nb = get_neighbor(r, c, d)
        if nb:
            nr, nc = nb
            od = OPP[d]
            if edges_state[nr][nc][od] is not None:
