    def extract_path(edges_h, edges_v):
        """Extract the loop path from ON edges."""
        adj = defaultdict(list)
        for r in range(N):
            for c in range(N-1):
                if edges_h[r][c] == ON:
                    adj[(r,c)].append((r,c+1))
