    # Backtracking search
    def backtrack(edges_h, edges_v, depth=0):
        unknowns = get_unknown_edges(edges_h, edges_v)

        if not unknowns:
            if is_complete(edges_h, edges_v) and validate_clues(edges_h, edges_v):
