        # Choose edge to branch on - prefer edges adjacent to clue cells
        best_key = None
        best_score = -1

        for key in unknowns:
            t, r, c = key
            if t == 'h':
                r1, c1, r2, c2 = r, c, r, c+1
            else:
                r1, c1, r2, c2 = r, c, r+1, c

            score = 0
            for rr, cc in [(r1,c1), (r2,c2)]:
