                    score += 10
                adj = get_adj_edges(rr, cc, edges_h, edges_v)
                on_count = sum(1 for d, nr, nc, v in adj if v == ON)
                unk_count = sum(1 for d, nr, nc, v in adj if v == UNKNOWN)
                score += on_count * 3 + (4 - unk_count)

            if score > best_score:
                best_score = score
                best_key = key

        key = best_key

        for val in [ON, OFF]:
            new_eh, new_ev = copy_edges(edges_h, edges_v)
            set_edge_by_key(key, val, new_eh, new_ev)

            if propagate(new_eh, new_ev):
                if validate_clues(new_eh, new_ev):
                    result = backtrack(new_eh, new_ev, depth+1)
                    if result is not None:
                        return result

        return None

    result = backtrack(eh, ev)

    if result is None:
        return "No Solution"

    final_eh, final_ev = result
    path = extract_path(final_eh, final_ev)

    if path is None:
        return "No Solution"

    return str(path)


