        # Find unknown edges
        unknown = [ek for ek, state in edge_state.items() if state is None]

        if not unknown:
            if is_valid_solution(edge_state):
                return edge_state
            return None

        # Check for premature loops
        if not check_no_premature_loop(edge_state):
            return None

        # Choose edge to branch on - prefer edges adjacent to clue nodes
        def edge_priority(ek):
            r1, c1, r2, c2 = ek
            score = 0
            for r, c in [(r1, c1), (r2, c2)]:
                if data[r][c] is not None:
                    score += 10
                in_e, out_e, unk_e = get_node_edges(r, c, edge_state)
                score += len(in_e) * 2
            return -score

        unknown.sort(key=edge_priority)
        ek = unknown[0]

        # Try True first, then False
        for val in [True, False]:
            new_state = dict(edge_state)
            new_state[ek] = val

            if propagate(new_state, [ek]):
                # Apply black constraints
                result = apply_black_constraints(new_state)
                if result is not False:
                    if result and not propagate(new_state, result):
                        continue

                    sol = backtrack(new_state)
                    if sol is not None:
                        return sol

        return None

    solution = backtrack(edge_state)

    if solution is None:
        return "No Solution"

    loop = extract_loop(solution)
    if loop is None:
        return "No Solution"

    return str(loop)


