def get_all_placements(clues, length):
    """Generate all valid binary rows/cols matching the clues."""
    results = []

    def backtrack(clue_idx, pos, current):
        if clue_idx == len(clues):
            # Fill rest with 0
            results.append(current + [0] * (length - len(current)))
            return
        run_len = clues[clue_idx]
        # Try placing this run at each valid position
