    def helper(clues, length, start):
        if not clues:
            yield []
            return
        clue = clues[0]
        rest = clues[1:]
        # minimum space needed for rest
        min_rest = sum(rest) + len(rest)
        for pos in range(start, length - clue - min_rest + 1):
            for tail in helper(rest, length, pos + clue + 1):
                yield [(pos, pos + clue - 1)] + tail

    return list(helper(clues, length, 0))

def compute_possible_cells(clues, length):
    """For each cell, determine if it can be black, white, or both."""
    placements = get_placements(clues, length)
    if not placements:
        return None, None

