            for i in range(s, e + 1):
                black_cells.add(i)
        for i in range(length):
            if i in black_cells:
                can_black[i] = True
            else:
                can_white[i] = True

    return can_black, can_white

def filter_placements(clues, length, known):
    """Filter placements consistent with known cell states.
    known[i] = 'B' (black), 'W' (white), or None (unknown)
    """
    placements = get_placements(clues, length)
    valid = []
    for placement in placements:
        black_cells = set()
        for (s, e) in placement:
            for i in range(s, e + 1):
