            if runs != col_clues[c]:
                return False
        return True

    def copy_grid(grid):
        return [list(row) for row in grid]

    def find_most_constrained(grid):
        """Find the cell with most constraints (fewest valid options)."""
        # Find first unknown cell in most constrained row/col
        best = None
        best_score = -1
        for r in range(nrows):
            for c in range(ncols):
                if grid[r][c] is None:
                    # Score based on how many unknowns remain in row and col
                    row_unknowns = sum(1 for x in grid[r] if x is None)
                    col_unknowns = sum(1 for rr in range(nrows) if grid[rr][c] is None)
                    score = nrows + ncols - row_unknowns - col_unknowns
                    if score > best_score:
                        best_score = score
                        best = (r, c)
