import copy

def solve(observation):
    data = observation['data']
    ROWS = len(data)
    COLS = len(data[0])

    # States: 'W' = white, 'B' = black, None = unknown
    grid = [[None]*COLS for _ in range(ROWS)]

    # Mark numbered cells as white
    clues = {}  # (r,c) -> number
    for r in range(ROWS):
        for c in range(COLS):
            if data[r][c] is not None:
                clues[(r,c)] = data[r][c]
                grid[r][c] = 'W'

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < ROWS and 0 <= nc < COLS:
                yield nr, nc

    def get_island(r, c, grid):
        """BFS to get all white cells connected to (r,c)"""
        visited = set()
        queue = deque([(r,c)])
        visited.add((r,c))
        while queue:
            cr, cc = queue.popleft()
            for nr, nc in neighbors(cr, cc):
                if (nr,nc) not in visited and grid[nr][nc] == 'W':
                    visited.add((nr,nc))
                    queue.append((nr,nc))
        return visited

    def count_clues_in_island(island, clues):
        return sum(1 for cell in island if cell in clues)

    def is_valid_partial(grid):
        """Check partial validity"""
        # Check no 2x2 all black
        for r in range(ROWS-1):
            for c in range(COLS-1):
                if (grid[r][c] == 'B' and grid[r+1][c] == 'B' and
                    grid[r][c+1] == 'B' and grid[r+1][c+1] == 'B'):
                    return False

        # Check white islands don't exceed their clue size and don't merge
        visited = set()
        for (r,c), num in clues.items():
            if (r,c) in visited:
                continue
            island = get_island(r, c, grid)
            visited |= island
            # Count clues in this island
            clue_count = count_clues_in_island(island, clues)
            if clue_count > 1:
                return False
            # Island size shouldn't exceed clue
            if len(island) > num:
                return False

        return True

    def is_complete(grid):
        """Check if grid is fully assigned"""
        for r in range(ROWS):
            for c in range(COLS):
                if grid[r][c] is None:
                    return False
        return True

    def check_solution(grid):
        """Full validity check for complete grid"""
        # Check no 2x2 all black
        for r in range(ROWS-1):
            for c in range(COLS-1):
                if (grid[r][c] == 'B' and grid[r+1][c] == 'B' and
                    grid[r][c+1] == 'B' and grid[r+1][c+1] == 'B'):
                    return False

        # Check white islands
        visited = set()
        for (r,c), num in clues.items():
            if (r,c) in visited:
                continue
            island = get_island(r, c, grid)
            visited |= island
            clue_count = count_clues_in_island(island, clues)
            if clue_count != 1:
                return False
            if len(island) != num:
                return False

        # Check all white cells are covered by exactly one island
        for r in range(ROWS):
            for c in range(COLS):
                if grid[r][c] == 'W' and (r,c) not in visited:
                    return False

        # Check black cells are connected
        black_cells = [(r,c) for r in range(ROWS) for c in range(COLS) if grid[r][c] == 'B']
        if not black_cells:
            return True

        visited_b = set()
        queue = deque([black_cells[0]])
        visited_b.add(black_cells[0])
        while queue:
            cr, cc = queue.popleft()
            for nr, nc in neighbors(cr, cc):
                if (nr,nc) not in visited_b and grid[nr][nc] == 'B':
                    visited_b.add((nr,nc))
                    queue.append((nr,nc))

        return len(visited_b) == len(black_cells)

