        """Apply constraint propagation rules"""
        changed = True
        while changed:
            changed = False

            # Rule 1: If a white island has reached its size, mark all adjacent unknowns as black
            visited = set()
            island_map = {}  # cell -> (island_set, clue_num)
            for (r,c), num in clues.items():
                island = get_island(r, c, grid)
                for cell in island:
                    island_map[cell] = (island, num)
                visited |= island

            for (r,c), num in clues.items():
                island = get_island(r, c, grid)
                if len(island) == num:
                    # Mark all adjacent unknowns as black
                    for cell in island:
