                            if grid[nr][nc] is None:
                                grid[nr][nc] = 'B'
                                changed = True

            # Rule 2: If adding a white cell would merge two islands, mark it black
            for r in range(ROWS):
                for c in range(COLS):
                    if grid[r][c] is None:
                        # Check if making this white would merge islands
                        adj_islands = set()
                        for nr, nc in neighbors(r, c):
                            if grid[nr][nc] == 'W':
                                # Find which clue this belongs to
                                for (cr, cc), num in clues.items():
                                    isl = get_island(cr, cc, grid)
                                    if (nr, nc) in isl:
                                        adj_islands.add((cr, cc))
                                        break
                        if len(adj_islands) > 1:
                            grid[r][c] = 'B'
                            changed = True

            # Rule 3: If an island can only expand in one direction, force it
            for (r,c), num in clues.items():
                island = get_island(r, c, grid)
                if len(island) < num:
                    # Find expandable cells
                    expandable = set()
                    for cell in island:
                        for nr, nc in neighbors(*cell):
                            if grid[nr][nc] is None:
                                expandable.add((nr, nc))
                    if len(expandable) == 0 and len(island) < num:
                        return None  # Dead end

            # Rule 4: Unreachable cells must be black
            # A cell is unreachable if no clue can reach it
            for r in range(ROWS):
                for c in range(COLS):
                    if grid[r][c] is None:
                        reachable = False
                        for (cr, cc), num in clues.items():
                            # BFS distance from clue to cell through non-black cells
                            dist = bfs_dist(cr, cc, r, c, grid, num)
                            if dist is not None and dist < num:
                                reachable = True
                                break
                        if not reachable:
                            grid[r][c] = 'B'
                            changed = True

            # Check validity
            if not is_valid_partial(grid):
                return None

        return grid

    def bfs_dist(sr, sc, tr, tc, grid, max_dist):
        """BFS distance avoiding black cells, limited by max_dist"""
        if grid[tr][tc] == 'B':
            return None
        visited = {(sr, sc): 0}
        queue = deque([(sr, sc, 0)])
        while queue:
            r, c, d = queue.popleft()
            if r == tr and c == tc:
                return d
            if d >= max_dist - 1:
                continue
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] != 'B':
                    visited[(nr, nc)] = d + 1
                    queue.append((nr, nc, d + 1))
        return None

    def get_unassigned(grid):
        """Get unassigned cells, prioritizing those with most constraints"""
        cells = []
        for r in range(ROWS):
            for c in range(COLS):
                if grid[r][c] is None:
                    cells.append((r, c))
        return cells

    def backtrack(grid):
        grid = propagate(grid)
        if grid is None:
            return None

        if is_complete(grid):
            if check_solution(grid):
                return grid
            return None

        # Find most constrained unassigned cell
        cells = get_unassigned(grid)
        if not cells:
            return None

        # Heuristic: pick cell adjacent to most assigned cells
        best = None
        best_score = -1
        for r, c in cells:
            score = sum(1 for nr, nc in neighbors(r, c) if grid[nr][nc] is not None)
            if score > best_score:
                best_score = score
                best = (r, c)

        r, c = best

        for color in ['B', 'W']:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = color

            if not is_valid_partial(new_grid):
                continue

            result = backtrack(new_grid)
            if result is not None:
                return result

        return None

    # Initial propagation
    result_grid = propagate(grid)
    if result_grid is None:
        return "No Solution"

    # Backtrack if needed
    result_grid = backtrack(result_grid)

    if result_grid is None:
        return "No Solution"

    # Format output
    output = []
    for r in range(ROWS):
        row = []
        for c in range(COLS):
            if result_grid[r][c] == 'B':
                row.append('B')
            else:
                row.append(None)
        output.append(row)

    return output

