    # Islands: list of (row, col, size)
    islands = []
    island_map = {}  # (r,c) -> island_id

    for r in range(ROWS):
        for c in range(COLS):
            if data[r][c] is not None:
                iid = len(islands)
                islands.append({'pos': (r,c), 'size': data[r][c], 'id': iid})
                island_map[(r,c)] = iid

    N_ISLANDS = len(islands)

    # State: grid of values
    # 'B' = black, None = unknown, integer = island_id (white)
    grid = [[None]*COLS for _ in range(ROWS)]

    # Mark numbered cells as their island
    for iid, isl in enumerate(islands):
        r, c = isl['pos']
        grid[r][c] = iid

    def get_neighbors(r, c):
        res = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < ROWS and 0 <= nc < COLS:
                res.append((nr, nc))
        return res

    def copy_grid(g):
        return [row[:] for row in g]

    def get_island_cells(g, iid):
        cells = set()
        for r in range(ROWS):
            for c in range(COLS):
                if g[r][c] == iid:
                    cells.add((r,c))
