        count = 0
        for r in range(ROWS):
            for c in range(COLS):
                if g[r][c] == iid:
                    count += 1
        return count

    def can_expand(g, iid):
        """Get unknown cells adjacent to island iid"""
        cells = get_island_cells(g, iid)
        frontier = set()
        for (r,c) in cells:
            for (nr,nc) in get_neighbors(r,c):
                if g[nr][nc] is None:
                    frontier.add((nr,nc))
        return frontier

    def check_no_2x2_black(g, r, c):
        """Check that placing black at (r,c) doesn't create 2x2"""
        for dr in [0,-1]:
            for dc in [0,-1]:
                r0, c0 = r+dr, c+dc
                if 0 <= r0 < ROWS-1 and 0 <= c0 < COLS-1:
                    if (g[r0][c0] == 'B' and g[r0][c0+1] == 'B' and
                        g[r0+1][c0] == 'B' and g[r0+1][c0+1] == 'B'):
                        return False
        return True

    def check_2x2_black(g):
        for r in range(ROWS-1):
            for c in range(COLS-1):
                if (g[r][c] == 'B' and g[r][c+1] == 'B' and
                    g[r+1][c] == 'B' and g[r+1][c+1] == 'B'):
                    return False
        return True

    def black_connected(g):
        """Check if all black cells are connected"""
        black_cells = [(r,c) for r in range(ROWS) for c in range(COLS) if g[r][c] == 'B']
        if not black_cells:
            return True
        visited = set()
        queue = deque([black_cells[0]])
        visited.add(black_cells[0])
        while queue:
            r,c = queue.popleft()
            for nr,nc in get_neighbors(r,c):
                if (nr,nc) not in visited and g[nr][nc] == 'B':
                    visited.add((nr,nc))
                    queue.append((nr,nc))
