    def islands_valid(g):
        """Check all islands have correct size and are connected"""
        for iid, isl in enumerate(islands):
            cells = get_island_cells(g, iid)
            if len(cells) != isl['size']:
                return False
            # Check connectivity
            if len(cells) == 0:
                return False
            start = next(iter(cells))
            visited = set()
            queue = deque([start])
            visited.add(start)
            while queue:
                r,c = queue.popleft()
                for nr,nc in get_neighbors(r,c):
                    if (nr,nc) not in visited and (nr,nc) in cells:
                        visited.add((nr,nc))
                        queue.append((nr,nc))
            if len(visited) != len(cells):
