    def pick_cell(g):
        """Pick unknown cell adjacent to an island that needs expansion, or any unknown"""
        # Priority 1: unknown cells adjacent to islands that need more cells
        for iid, isl in enumerate(islands):
            cells = get_island_cells(g, iid)
            needed = isl['size'] - len(cells)
            if needed > 0:
