            return None

        # Find a cell to branch on
        # Strategy: find an island that needs expansion
        best_cell = None
        best_iid = None
        best_frontier_size = float('inf')

        for iid, isl in enumerate(islands):
            cells = get_island_cells(g, iid)
            needed = isl['size'] - len(cells)
            if needed > 0:
                frontier = can_expand(g, iid)
                if len(frontier) == 0:
                    return None  # Island can't expand but needs to
                if len(frontier) < best_frontier_size:
                    best_frontier_size = len(frontier)
                    best_cell = next(iter(frontier))
                    best_iid = iid

        if best_cell is None:
