def solve(observation):
    data = observation['data']
    adjacent_list = observation['adjacent']

    N = len(data)

    # Build adjacency set for quick lookup
    # dot_between[(r1,c1),(r2,c2)] = True means consecutive required
    dot_set = set()
    for coord in adjacent_list:
        r, c = coord[0], coord[1]
        if r == int(r):  # horizontal dot between (r, c-0.5) and (r, c+0.5) -> cells (r, floor(c)) and (r, ceil(c))
            row = int(r)
            col1 = int(c - 0.5)
            col2 = int(c + 0.5)
            dot_set.add((row, col1, row, col2))
            dot_set.add((row, col2, row, col1))
        else:  # vertical dot
            row1 = int(r - 0.5)
            row2 = int(r + 0.5)
            col = int(c)
            dot_set.add((row1, col, row2, col))
            dot_set.add((row2, col, row1, col))

    # For each pair of orthogonally adjacent cells, determine if they have a dot
    def has_dot(r1, c1, r2, c2):
        return (r1, c1, r2, c2) in dot_set

    # Initialize grid
    grid = [[None]*N for _ in range(N)]

    # Candidates for each cell: set of possible values
    candidates = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]

    # Apply given clues
    def assign(grid, candidates, row, col, val):
        """Assign val to grid[row][col], propagate constraints. Returns False if contradiction."""
        if grid[row][col] is not None:
            return grid[row][col] == val

        grid[row][col] = val
        candidates[row][col] = {val}

        # Remove val from same row and column
        for c in range(N):
            if c != col and val in candidates[row][c]:
                candidates[row][c].discard(val)
                if len(candidates[row][c]) == 0:
                    return False
        for r in range(N):
            if r != row and val in candidates[r][col]:
                candidates[r][col].discard(val)
                if len(candidates[r][col]) == 0:
                    return False

        return True

    def get_neighbors(r, c):
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < N-1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < N-1: neighbors.append((r, c+1))
        return neighbors

    def is_valid_assignment(grid, r, c, val):
        """Check if assigning val to (r,c) is consistent with dot constraints."""
        for nr, nc in get_neighbors(r, c):
            nval = grid[nr][nc]
            if has_dot(r, c, nr, nc):
                # Must be consecutive
                if nval is not None:
                    if abs(val - nval) != 1:
                        return False
                # If neighbor not assigned, check if any consecutive value is possible
                else:
                    consec = {val-1, val+1} & set(range(1, N+1))
                    if not consec & candidates[nr][nc]:
                        return False
            else:
                # Must NOT be consecutive
                if nval is not None:
                    if abs(val - nval) == 1:
                        return False
                # If neighbor not assigned, check if there's at least one non-consecutive value possible
                else:
                    non_consec = candidates[nr][nc] - {val-1, val+1}
                    if not non_consec:
                        return False
        return True

    def propagate_dot_constraints(grid, candidates):
        """Propagate dot/no-dot constraints to reduce candidates."""
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is not None:
                        continue
                    new_cands = set()
                    for val in candidates[r][c]:
                        valid = True
                        for nr, nc in get_neighbors(r, c):
                            if has_dot(r, c, nr, nc):
                                # val must have a consecutive neighbor possible
                                consec = {val-1, val+1} & set(range(1, N+1))
                                if grid[nr][nc] is not None:
                                    if abs(val - grid[nr][nc]) != 1:
                                        valid = False
                                        break
                                else:
                                    if not consec & candidates[nr][nc]:
                                        valid = False
                                        break
                            else:
                                # val must not be consecutive with neighbor
                                if grid[nr][nc] is not None:
                                    if abs(val - grid[nr][nc]) == 1:
                                        valid = False
                                        break
                                else:
                                    non_consec = candidates[nr][nc] - {val-1, val+1}
                                    if not non_consec:
                                        valid = False
                                        break
                        if valid:
                            new_cands.add(val)
                    if new_cands != candidates[r][c]:
                        candidates[r][c] = new_cands
                        changed = True
                        if len(new_cands) == 0:
                            return False
                        if len(new_cands) == 1:
                            val = next(iter(new_cands))
                            if not assign(grid, candidates, r, c, val):
                                return False
        return True

    def propagate_latin(grid, candidates):
        """Propagate latin square constraints (naked singles, hidden singles)."""
        changed = True
        while changed:
            changed = False
            # Naked singles
            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None and len(candidates[r][c]) == 1:
                        val = next(iter(candidates[r][c]))
                        if not assign(grid, candidates, r, c, val):
                            return False
                        changed = True

            # Hidden singles in rows
            for r in range(N):
                for val in range(1, N+1):
                    positions = [c for c in range(N) if grid[r][c] is None and val in candidates[r][c]]
                    if len(positions) == 0:
                        if val not in [grid[r][c] for c in range(N) if grid[r][c] is not None]:
                            return False
                    elif len(positions) == 1:
                        c = positions[0]
                        if not assign(grid, candidates, r, c, val):
                            return False
                        changed = True

            # Hidden singles in columns
            for c in range(N):
                for val in range(1, N+1):
                    positions = [r for r in range(N) if grid[r][c] is None and val in candidates[r][c]]
                    if len(positions) == 0:
                        if val not in [grid[r][c] for r in range(N) if grid[r][c] is not None]:
                            return False
                    elif len(positions) == 1:
                        r = positions[0]
                        if not assign(grid, candidates, r, c, val):
                            return False
                        changed = True
        return True

    def full_propagate(grid, candidates):
        changed = True
        while changed:
            changed = False
            prev_state = [[grid[r][c] for c in range(N)] for r in range(N)]

            if not propagate_latin(grid, candidates):
                return False
            if not propagate_dot_constraints(grid, candidates):
                return False

            new_state = [[grid[r][c] for c in range(N)] for r in range(N)]
            if new_state != prev_state:
                changed = True
        return True

    def copy_state(grid, candidates):
        g = [row[:] for row in grid]
        c = [list(map(set, row)) for row in candidates]
        return g, c

    def backtrack(grid, candidates):
        if not full_propagate(grid, candidates):
            return None

        # Check if solved
        if all(grid[r][c] is not None for r in range(N) for c in range(N)):
            # Verify solution
            return grid

        # Find cell with minimum candidates (MRV heuristic)
        min_len = N + 1
        best = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    l = len(candidates[r][c])
                    if l == 0:
                        return None
                    if l < min_len:
                        min_len = l
                        best = (r, c)

        if best is None:
            return grid

        r, c = best
        for val in sorted(candidates[r][c]):
            g2, cands2 = copy_state(grid, candidates)
            if assign(g2, cands2, r, c, val):
                result = backtrack(g2, cands2)
                if result is not None:
                    return result

        return None

    # Initialize with given clues
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                if not assign(grid, candidates, r, c, data[r][c]):
                    return "No Solution"

    result = backtrack(grid, candidates)

    if result is None:
        return "No Solution"

    return result

if __name__ == "__main__":
