            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)

        # Check for any node with degree > 2
        for node, nbs in adj.items():
            if len(nbs) > 2:
                return False

        # Check for cycles using DFS
        visited = {}

        def has_cycle(node, parent, comp):
            visited[node] = comp
