            # Check if we have a valid complete loop
            if is_complete_valid_loop(es):
                return es
            return None

        # Choose edge to branch on - prefer edges adjacent to clues
        # Heuristic: pick edge with most constraints
        best_edge = None
        best_score = -1

        for ek in undecided[:50]:  # Limit search
            a, b = ek
            score = 0
            if a in clues: score += 3
            if b in clues: score += 3
            # Count how many neighbors are decided
            for dot in [a, b]:
                r, c = dot
                on, off, unk = count_edges(r, c, es)
                score += on * 2 + off
            if score > best_score:
                best_score = score
                best_edge = ek

        if best_edge is None:
            best_edge = undecided[0]

        # Try True first
        for val in [True, False]:
            new_es = dict(es)
            new_es[best_edge] = val
            changed = {best_edge}

            if propagate(new_es, changed):
                if check_no_premature_cycle(new_es):
                    result = backtrack(new_es)
                    if result is not None:
                        return result

        return None

    result = backtrack(edge_state)

    if result is None:
        return "No Solution"

    loop = extract_loop(result)
    if loop is None:
        return "No Solution"

    return str(loop)


