            result.append((r, c+1, ('H', r, c)))
        if c - 1 >= 0:
            result.append((r, c-1, ('H', r, c-1)))
        if r + 1 < N:
            result.append((r+1, c, ('V', r, c)))
        if r - 1 >= 0:
            result.append((r-1, c, ('V', r-1, c)))
