        if d == 'U': return (r-1, c)
        if d == 'D': return (r+1, c)
        if d == 'L': return (r, c-1)
        if d == 'R': return (r, c+1)

    def opposite(d):
        return {'U':'D','D':'U','L':'R','R':'L'}[d]

