from itertools import permutations

def count_visible(row):
    """Count visible buildings from left side of a sequence."""
    visible = 0
    max_h = 0
    for h in row:
        if h > max_h:
            visible += 1
            max_h = h
    return visible

def is_valid_clue(sequence, clue):
    """Check if a complete sequence satisfies a clue (0 means no clue)."""
    if clue == 0:
        return True
    return count_visible(sequence) == clue

def get_clue_valid_perms(n, clue):
    """Get all permutations of 1..n that satisfy a given clue."""
    if clue == 0:
        return list(permutations(range(1, n+1)))
    return [p for p in permutations(range(1, n+1)) if count_visible(p) == clue]

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    n = len(U)

    # possibilities[r][c] = set of possible values for cell (r,c)
    possibilities = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    # Precompute valid permutations for each row and column clue
    # row_perms[r] = list of valid (left_clue, right_clue) permutations
    # col_perms[c] = list of valid (up_clue, down_clue) permutations

    row_valid = []
    for r in range(n):
        lc = L[r]
        rc = R[r]
        valid = []
        for p in permutations(range(1, n+1)):
            if (lc == 0 or count_visible(p) == lc) and \
               (rc == 0 or count_visible(p[::-1]) == rc):
                valid.append(p)
        row_valid.append(valid)

    col_valid = []
    for c in range(n):
        uc = U[c]
        dc = D[c]
        valid = []
        for p in permutations(range(1, n+1)):
            if (uc == 0 or count_visible(p) == uc) and \
               (dc == 0 or count_visible(p[::-1]) == dc):
                valid.append(p)
        col_valid.append(valid)

    # Propagate constraints from clue-valid permutations
    def propagate_from_clues(possibilities):
        changed = True
        while changed:
            changed = False
            # Row propagation
            for r in range(n):
                valid = [p for p in row_valid[r] 
                        if all(p[c] in possibilities[r][c] for c in range(n))]
                row_valid[r] = valid
                if not valid:
                    return False
                for c in range(n):
                    new_poss = set(p[c] for p in valid)
                    if new_poss < possibilities[r][c]:
                        possibilities[r][c] = new_poss
                        changed = True
                    if not possibilities[r][c]:
                        return False

            # Column propagation
            for c in range(n):
                valid = [p for p in col_valid[c]
                        if all(p[r] in possibilities[r][c] for r in range(n))]
                col_valid[c] = valid
                if not valid:
                    return False
                for r in range(n):
                    new_poss = set(p[r] for p in valid)
                    if new_poss < possibilities[r][c]:
                        possibilities[r][c] = new_poss
                        changed = True
                    if not possibilities[r][c]:
                        return False
        return True

    def is_consistent(grid, r, c, val):
        """Check if placing val at (r,c) is consistent with current grid."""
        # Check row uniqueness
        for cc in range(n):
            if cc != c and grid[r][cc] == val:
                return False
        # Check col uniqueness
        for rr in range(n):
            if rr != r and grid[rr][c] == val:
                return False
        return True

    def check_partial_clue(seq, clue_from_start, clue_from_end, length):
        """Check partial sequence against clues - pruning."""
        if clue_from_start != 0:
            # Count visible so far
            vis = 0
            mx = 0
            for h in seq:
                if h > mx:
                    vis += 1
                    mx = h
            if vis > clue_from_start:
                return False
            # If sequence complete
            if len(seq) == length and vis != clue_from_start:
                return False
        if clue_from_end != 0 and len(seq) == length:
            vis = 0
            mx = 0
            for h in reversed(seq):
                if h > mx:
                    vis += 1
                    mx = h
            if vis != clue_from_end:
                return False
        return True

    # Backtracking solver
    def backtrack(grid, poss):
        # Find cell with minimum possibilities (MRV heuristic)
        min_count = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    cnt = len(poss[r][c])
                    if cnt == 0:
                        return None
                    if cnt < min_count:
                        min_count = cnt
                        best = (r, c)

        if best is None:
            # All filled - verify all clues
            for r in range(n):
                row = grid[r]
                if L[r] != 0 and count_visible(row) != L[r]:
                    return None
                if R[r] != 0 and count_visible(row[::-1]) != R[r]:
                    return None
            for c in range(n):
                col = [grid[r][c] for r in range(n)]
                if U[c] != 0 and count_visible(col) != U[c]:
                    return None
                if D[c] != 0 and count_visible(col[::-1]) != D[c]:
                    return None
            return grid

        r, c = best

        for val in sorted(poss[r][c]):
            if not is_consistent(grid, r, c, val):
                continue

            # Make a copy and place value
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val

            # Copy possibilities and update
            new_poss = [row[:] for row in poss]
            new_poss[r] = [s.copy() for s in poss[r]]
            for rr in range(n):
                new_poss[rr] = [s.copy() for s in poss[rr]]

            new_poss[r][c] = {val}

            # Propagate: remove val from row and col
            valid = True
            for cc in range(n):
                if cc != c and val in new_poss[r][cc]:
                    new_poss[r][cc].discard(val)
                    if not new_poss[r][cc]:
                        valid = False
                        break
            if valid:
                for rr in range(n):
                    if rr != r and val in new_poss[rr][c]:
                        new_poss[rr][c].discard(val)
                        if not new_poss[rr][c]:
                            valid = False
                            break

            if not valid:
                continue

            # Re-filter row_valid and col_valid for affected row/col
            saved_rv = row_valid[r][:]
            saved_cv = col_valid[c][:]

            row_valid[r] = [p for p in row_valid[r]
                           if all(p[cc] in new_poss[r][cc] for cc in range(n))]
            col_valid[c] = [p for p in col_valid[c]
                           if all(p[rr] in new_poss[rr][c] for rr in range(n))]

            if not row_valid[r] or not col_valid[c]:
                row_valid[r] = saved_rv
                col_valid[c] = saved_cv
                continue

            # Propagate
            if propagate_from_clues(new_poss):
                result = backtrack(new_grid, new_poss)
                if result is not None:
                    return result

            row_valid[r] = saved_rv
            col_valid[c] = saved_cv

        return None

    # Initialize grid
    grid = [[0]*n for _ in range(n)]

    # Initial propagation
    if not propagate_from_clues(possibilities):
        return "No Solution"

    # Apply naked singles
    changed = True
    while changed:
        changed = False
        for r in range(n):
            for c in range(n):
                if len(possibilities[r][c]) == 1:
                    val = next(iter(possibilities[r][c]))
                    if grid[r][c] == 0:
                        grid[r][c] = val
                        changed = True
                        # Remove from row/col
                        for cc in range(n):
                            if cc != c:
                                possibilities[r][cc].discard(val)
                        for rr in range(n):
                            if rr != r:
                                possibilities[rr][c].discard(val)

    result = backtrack(grid, possibilities)

    if result is None:
        return "No Solution"

    return result

