def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    n = len(U)

    # domains[r][c] = set of possible values for cell (r, c)
    domains = [[set(range(1, n + 1)) for _ in range(n)] for _ in range(n)]

    def propagate():
        """Propagate constraints using arc consistency."""
        changed = True
