                            domains[r][c2].discard(val)
                            changed = True
                            if len(domains[r][c2]) == 0:
                                return False
            # Col uniqueness
            for c in range(n):
                singles = [r for r in range(n) if len(domains[r][c]) == 1]
                for r in singles:
                    val = next(iter(domains[r][c]))
                    for r2 in range(n):
                        if r2 != r and val in domains[r2][c]:
                            domains[r2][c].discard(val)
                            changed = True
                            if len(domains[r2][c]) == 0:
                                return False
            # Clue-based pruning for rows
            for r in range(n):
                l_clue = L[r]
                r_clue = R[r]
                if l_clue != 0 or r_clue != 0:
                    # Get current domain for this row
                    row_domains = [domains[r][c] for c in range(n)]
                    # Find valid permutations
                    valid_perms = []
                    # Only enumerate if domains are small enough
                    total = 1
                    for d in row_domains:
                        total *= len(d)
                    if total <= 100000:
                        def gen_row(col, current, used):
                            if col == n:
                                if is_valid_clue(current, l_clue) and is_valid_clue(list(reversed(current)), r_clue):
                                    valid_perms.append(tuple(current))
                                return
                            for v in row_domains[col]:
                                if v not in used:
                                    current.append(v)
                                    used.add(v)
                                    gen_row(col + 1, current, used)
                                    current.pop()
                                    used.remove(v)
                        gen_row(0, [], set())
                        if len(valid_perms) == 0:
                            return False
                        # Intersect domains
                        for c in range(n):
                            new_vals = set(p[c] for p in valid_perms)
                            if not new_vals.issubset(domains[r][c]):
                                domains[r][c] &= new_vals
                                changed = True
                            if len(domains[r][c]) == 0:
                                return False
            # Clue-based pruning for cols
            for c in range(n):
                u_clue = U[c]
                d_clue = D[c]
                if u_clue != 0 or d_clue != 0:
                    col_domains = [domains[r][c] for r in range(n)]
                    valid_perms = []
                    total = 1
                    for d in col_domains:
                        total *= len(d)
                    if total <= 100000:
                        def gen_col(row, current, used):
                            if row == n:
                                if is_valid_clue(current, u_clue) and is_valid_clue(list(reversed(current)), d_clue):
                                    valid_perms.append(tuple(current))
                                return
                            for v in col_domains[row]:
                                if v not in used:
                                    current.append(v)
                                    used.add(v)
                                    gen_col(row + 1, current, used)
                                    current.pop()
                                    used.remove(v)
                        gen_col(0, [], set())
                        if len(valid_perms) == 0:
                            return False
                        for r in range(n):
                            new_vals = set(p[r] for p in valid_perms)
                            if not new_vals.issubset(domains[r][c]):
                                domains[r][c] &= new_vals
                                changed = True
                            if len(domains[r][c]) == 0:
                                return False
        return True

    def is_complete():
        return all(len(domains[r][c]) == 1 for r in range(n) for c in range(n))

    def is_consistent(grid):
        """Check if a complete grid satisfies all clues."""
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if not is_valid_clue(col, U[c]):
                return False
            if not is_valid_clue(list(reversed(col)), D[c]):
                return False
        for r in range(n):
            row = [grid[r][c] for c in range(n)]
            if not is_valid_clue(row, L[r]):
                return False
            if not is_valid_clue(list(reversed(row)), R[r]):
                return False
        return True

    def backtrack():
        if not propagate():
            return False
        if is_complete():
            return True
        # Find cell with minimum domain size > 1 (MRV heuristic)
        min_size = n + 1
        best = None
        for r in range(n):
            for c in range(n):
                s = len(domains[r][c])
                if s == 0:
                    return False
                if 1 < s < min_size:
                    min_size = s
                    best = (r, c)
        if best is None:
            return True
        r, c = best
        # Try each value
        saved = [[set(domains[row][col]) for col in range(n)] for row in range(n)]
        for val in sorted(domains[r][c]):
            # Restore domains
            for row in range(n):
                for col in range(n):
                    domains[row][col] = set(saved[row][col])
            domains[r][c] = {val}
            if backtrack():
                return True
        # Restore on failure
        for row in range(n):
            for col in range(n):
                domains[row][col] = set(saved[row][col])
        return False

    if not backtrack():
        return "No Solution"

    grid = [[next(iter(domains[r][c])) for c in range(n)] for r in range(n)]

    if not is_consistent(grid):
        return "No Solution"

    return grid

