# Skyscrapers puzzle solver using constraint propagation + backtracking

def count_visible(line):
    """Count visible buildings from the left of a line."""
    max_h = 0
    count = 0
    for h in line:
        if h > max_h:
            count += 1
            max_h = h
    return count

def is_valid_clue(line, clue):
    """Check if a complete line satisfies the clue (0 means no clue)."""
    if clue == 0:
        return True
    return count_visible(line) == clue

def can_satisfy_clue(partial_line, clue, n):
    """
    Check if a partial line can still satisfy the clue.
    partial_line may contain 0s for unfilled cells.
    """
    if clue == 0:
        return True

    filled = [x for x in partial_line if x != 0]
    length = len(partial_line)

    # Count definite visible buildings so far
    max_h = 0
    definite_visible = 0
    for h in partial_line:
        if h == 0:
            break
        if h > max_h:
            definite_visible += 1
            max_h = h

    # If we've processed all filled cells from the start (no gaps)
    prefix_len = 0
    for h in partial_line:
        if h == 0:
            break
        prefix_len += 1

    if prefix_len == length:
        # Complete line
        return count_visible(partial_line) == clue

    # Minimum possible visible: definite_visible (can't decrease)
    # Maximum possible visible: definite_visible + remaining cells
    remaining = length - prefix_len
    max_possible = definite_visible + remaining

    if definite_visible > clue:
        return False
    if max_possible < clue:
        return False

    return True

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    n = len(U)

    # grid[r][c] = 0 means unfilled
    grid = [[0] * n for _ in range(n)]

    # Possible values for each cell
    possible = [[set(range(1, n+1)) for _ in range(n)] for _ in range(n)]

    def get_row(r):
        return grid[r][:]

    def get_col(c):
        return [grid[r][c] for r in range(n)]

    def propagate():
        """Propagate constraints using arc consistency."""
        changed = True
        while changed:
            changed = False
            for r in range(n):
                for c in range(n):
                    if grid[r][c] != 0:
                        continue
                    # Remove values already in row/col
                    row_vals = set(grid[r][cc] for cc in range(n) if grid[r][cc] != 0)
                    col_vals = set(grid[rr][c] for rr in range(n) if grid[rr][c] != 0)
                    new_poss = possible[r][c] - row_vals - col_vals
                    if new_poss != possible[r][c]:
                        possible[r][c] = new_poss
                        changed = True
                    if len(possible[r][c]) == 0:
                        return False
                    if len(possible[r][c]) == 1:
                        val = next(iter(possible[r][c]))
                        if not assign(r, c, val):
                            return False
                        changed = True

            # Apply clue-based deductions
            if not apply_clue_deductions():
                return False

        return True

    def assign(r, c, val):
        """Assign a value to a cell."""
        if grid[r][c] == val:
            return True
        if grid[r][c] != 0:
            return False
        grid[r][c] = val
        possible[r][c] = {val}
        return True

    def apply_clue_deductions():
        """Apply deductions based on clues."""
        # For clue=1, the first cell must be N
        # For clue=N, must be 1,2,...,N in order
        for c in range(n):
            if U[c] == 1:
                if not assign(0, c, n):
                    return False
            if D[c] == 1:
                if not assign(n-1, c, n):
                    return False
            if U[c] == n:
                for r in range(n):
                    if not assign(r, c, r+1):
                        return False
            if D[c] == n:
                for r in range(n):
                    if not assign(r, c, n-r):
                        return False

        for r in range(n):
            if L[r] == 1:
                if not assign(r, 0, n):
                    return False
            if R[r] == 1:
                if not assign(r, n-1, n):
                    return False
            if L[r] == n:
                for c in range(n):
                    if not assign(r, c, c+1):
                        return False
            if R[r] == n:
                for c in range(n):
                    if not assign(r, c, n-c):
                        return False

        return True

    def is_consistent():
        """Check if current partial grid is consistent with all clues."""
        for r in range(n):
            row = get_row(r)
            # Check row uniqueness
            filled = [x for x in row if x != 0]
            if len(filled) != len(set(filled)):
                return False
            # Check L clue
            if L[r] != 0:
                if not can_satisfy_clue(row, L[r], n):
                    return False
            # Check R clue
            if R[r] != 0:
                rev_row = row[::-1]
                if not can_satisfy_clue(rev_row, R[r], n):
                    return False

        for c in range(n):
            col = get_col(c)
            # Check col uniqueness
            filled = [x for x in col if x != 0]
            if len(filled) != len(set(filled)):
                return False
            # Check U clue
            if U[c] != 0:
                if not can_satisfy_clue(col, U[c], n):
                    return False
            # Check D clue
            if D[c] != 0:
                rev_col = col[::-1]
                if not can_satisfy_clue(rev_col, D[c], n):
                    return False

        return True

    def is_complete():
        """Check if grid is completely filled."""
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def is_solution():
        """Check if complete grid satisfies all clues."""
        for r in range(n):
            row = get_row(r)
            if sorted(row) != list(range(1, n+1)):
                return False
            if L[r] != 0 and count_visible(row) != L[r]:
                return False
            if R[r] != 0 and count_visible(row[::-1]) != R[r]:
                return False
        for c in range(n):
            col = get_col(c)
            if sorted(col) != list(range(1, n+1)):
                return False
            if U[c] != 0 and count_visible(col) != U[c]:
                return False
            if D[c] != 0 and count_visible(col[::-1]) != D[c]:
                return False
        return True

    def find_best_cell():
        """Find the unfilled cell with fewest possibilities (MRV heuristic)."""
        best = None
        best_count = n + 1
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    # Compute actual possibilities
                    row_vals = set(grid[r][cc] for cc in range(n) if grid[r][cc] != 0)
                    col_vals = set(grid[rr][c] for rr in range(n) if grid[rr][c] != 0)
                    poss = possible[r][c] - row_vals - col_vals
                    possible[r][c] = poss
                    cnt = len(poss)
                    if cnt == 0:
                        return None, None, None
                    if cnt < best_count:
                        best_count = cnt
                        best = (r, c)
                        if cnt == 1:
                            return r, c, poss
        if best is None:
            return None, None, None
        r, c = best
        return r, c, possible[r][c]

    import copy

    def backtrack():
        """Backtracking search with constraint propagation."""
        if is_complete():
            return is_solution()

        r, c, poss = find_best_cell()
        if r is None:
            return False
        if poss is None or len(poss) == 0:
            return False

        # Order values by some heuristic
        values = sorted(poss)

        for val in values:
            # Save state
            saved_grid = [row[:] for row in grid]
            saved_possible = [row[:] for row in possible]

            # Assign
            grid[r][c] = val
            possible[r][c] = {val}

            # Propagate
            if propagate() and is_consistent():
                if backtrack():
                    return True

            # Restore state
            for rr in range(n):
                grid[rr] = saved_grid[rr][:]
                possible[rr] = saved_possible[rr][:]

        return False

    # Initial propagation
    if not apply_clue_deductions():
        return "No Solution"
    if not propagate():
        return "No Solution"
    if not is_consistent():
        return "No Solution"

    # Backtrack
    if backtrack():
        return [row[:] for row in grid]

    return "No Solution"

