# Slash puzzle solver using constraint propagation + backtracking with union-find for cycle detection

from copy import deepcopy

def solve(observation):
    data = observation['data']
    N1 = len(data)
    N = N1 - 1  # grid is N x N cells, (N+1)x(N+1) dots

    # For each cell (r,c), '/' connects dots (r, c+1) and (r+1, c)
    #                       '\' connects dots (r, c) and (r+1, c+1)
    # dot_segments[r][c] = list of cells that have a diagonal incident to dot (r,c)
    # and what type makes it incident

    # Precompute for each dot (dr, dc), which cells and which slash type contribute
    # dot (dr, dc) is incident to:
    #   cell (dr-1, dc-1) with '\' (bottom-right corner)
    #   cell (dr-1, dc) with '/' (bottom-left corner)
    #   cell (dr, dc-1) with '/' (top-right corner)
    #   cell (dr, dc) with '\' (top-left corner)

    def get_incident_cells(dr, dc):
        """Returns list of (cell_r, cell_c, slash_type) incident to dot (dr, dc)"""
        result = []
        # cell (dr-1, dc-1) with '\'
        if 0 <= dr-1 < N and 0 <= dc-1 < N:
            result.append((dr-1, dc-1, '\\'))
        # cell (dr-1, dc) with '/'
        if 0 <= dr-1 < N and 0 <= dc < N:
            result.append((dr-1, dc, '/'))
        # cell (dr, dc-1) with '/'
        if 0 <= dr < N and 0 <= dc-1 < N:
            result.append((dr, dc-1, '/'))
        # cell (dr, dc) with '\'
        if 0 <= dr < N and 0 <= dc < N:
            result.append((dr, dc, '\\'))
        return result

    # Precompute clues
    clues = {}
    for r in range(N1):
        for c in range(N1):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    # Grid: None = unassigned, '/' or '\'
    grid = [[None]*N for _ in range(N)]

    # Union-Find for cycle detection
    # Nodes are the (N+1)*(N+1) dots
    # Each diagonal connects two dots; we must not form a cycle

    def dot_id(r, c):
        return r * N1 + c

    class UnionFind:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0]*n

        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, x, y):
            rx, ry = self.find(x), self.find(y)
            if rx == ry:
                return False  # cycle
            if self.rank[rx] < self.rank[ry]:
                rx, ry = ry, rx
            self.parent[ry] = rx
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1
            return True

        def copy(self):
            uf = UnionFind(0)
            uf.parent = self.parent[:]
            uf.rank = self.rank[:]
            return uf

    # For each dot, track how many segments are assigned
    # dot_count[r][c] = current count of assigned diagonals incident to it
    dot_count = [[0]*N1 for _ in range(N1)]
    # dot_possible[r][c] = number of unassigned cells incident to it
    dot_possible = [[0]*N1 for _ in range(N1)]

    # Initialize dot_possible
    for dr in range(N1):
        for dc in range(N1):
            dot_possible[dr][dc] = len(get_incident_cells(dr, dc))

    # Cell connections: which two dots does each slash type connect?
    def cell_dots(r, c, slash):
        if slash == '/':
            return (r+1, c), (r, c+1)
        else:  # '\'
            return (r, c), (r+1, c+1)

    def is_valid_assignment(grid, dot_count, dot_possible, clues, r, c, slash, uf):
        """Check if assigning slash to cell (r,c) is locally valid"""
        d1, d2 = cell_dots(r, c, slash)

        # Check cycle
        if uf.find(dot_id(*d1)) == uf.find(dot_id(*d2)):
            return False

        # Check dot constraints for affected dots
        for dr, dc in [d1, d2]:
            new_count = dot_count[dr][dc] + 1
            if (dr, dc) in clues:
                if new_count > clues[(dr, dc)]:
                    return False

        return True

    def forward_check(grid, dot_count, dot_possible, clues):
        """Check if all clue dots can still be satisfied"""
        for (dr, dc), clue_val in clues.items():
            current = dot_count[dr][dc]
            possible = dot_possible[dr][dc]
            if current > clue_val:
                return False
            if current + possible < clue_val:
                return False
        return True

    def get_forced_cells(grid, dot_count, dot_possible, clues):
        """Find cells that are forced by constraints"""
        forced = {}  # cell -> slash type

        for (dr, dc), clue_val in clues.items():
            current = dot_count[dr][dc]
            remaining_needed = clue_val - current
            incident = get_incident_cells(dr, dc)
            unassigned = [(r, c, s) for r, c, s in incident if grid[r][c] is None]

            if remaining_needed == len(unassigned):
                # All unassigned must be assigned the correct type
                for r, c, s in unassigned:
                    if (r, c) in forced and forced[(r, c)] != s:
                        return None  # contradiction
                    forced[(r, c)] = s
            elif remaining_needed == 0:
                # All unassigned must be assigned the opposite type
                for r, c, s in unassigned:
                    opp = '/' if s == '\\' else '\\'
                    if (r, c) in forced and forced[(r, c)] != opp:
                        return None  # contradiction
                    forced[(r, c)] = opp

        return forced

    def propagate(grid, dot_count, dot_possible, clues, uf):
        """Propagate constraints, return False if contradiction"""
        changed = True
        while changed:
            changed = False
            forced = get_forced_cells(grid, dot_count, dot_possible, clues)
            if forced is None:
                return False

            for (r, c), slash in forced.items():
                if grid[r][c] is not None:
                    if grid[r][c] != slash:
                        return False
                    continue

                # Check validity
                if not is_valid_assignment(grid, dot_count, dot_possible, clues, r, c, slash, uf):
                    return False

                # Assign
                assign(grid, dot_count, dot_possible, r, c, slash, uf)
                changed = True

            if not forward_check(grid, dot_count, dot_possible, clues):
                return False

        return True

    def assign(grid, dot_count, dot_possible, r, c, slash, uf):
        """Assign slash to cell (r,c) and update counts"""
        grid[r][c] = slash
        d1, d2 = cell_dots(r, c, slash)
        uf.union(dot_id(*d1), dot_id(*d2))

        # Update dot_count and dot_possible for all incident dots of this cell
        # For the two dots connected by this slash
        dot_count[d1[0]][d1[1]] += 1
        dot_count[d2[0]][d2[1]] += 1

        # Update dot_possible for all 4 corner dots of this cell
        for dr, dc in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
            dot_possible[dr][dc] -= 1

    def unassign(grid, dot_count, dot_possible, r, c, slash, uf_parent_backup, uf_rank_backup):
        """Unassign cell (r,c)"""
        d1, d2 = cell_dots(r, c, slash)
        dot_count[d1[0]][d1[1]] -= 1
        dot_count[d2[0]][d2[1]] -= 1

        for dr, dc in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
            dot_possible[dr][dc] += 1

        grid[r][c] = None
        # Restore UF
        return uf_parent_backup, uf_rank_backup

    def pick_cell(grid):
        """Pick unassigned cell with most constraints (MRV heuristic)"""
        best = None
        best_score = -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    # Score: number of clue dots incident to this cell
                    score = 0
                    for dr, dc in [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]:
                        if (dr, dc) in clues:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best = (r, c)
        return best

    def backtrack(grid, dot_count, dot_possible, uf):
        # Propagate first
        # Make deep copies for backtracking
        grid_copy = [row[:] for row in grid]
        dc_copy = [row[:] for row in dot_count]
        dp_copy = [row[:] for row in dot_possible]
        uf_copy = uf.copy()

        if not propagate(grid_copy, dc_copy, dp_copy, clues, uf_copy):
            return None

        # Check if solved
        cell = pick_cell(grid_copy)
        if cell is None:
            # All assigned, verify
            for (dr, dc), clue_val in clues.items():
                if dc_copy[dr][dc] != clue_val:
                    return None
            return grid_copy

        r, c = cell

        for slash in ['/', '\\']:
            if not is_valid_assignment(grid_copy, dc_copy, dp_copy, clues, r, c, slash, uf_copy):
                continue

            # Make copies
            g2 = [row[:] for row in grid_copy]
            dc2 = [row[:] for row in dc_copy]
            dp2 = [row[:] for row in dp_copy]
            uf2 = uf_copy.copy()

            assign(g2, dc2, dp2, r, c, slash, uf2)

            result = backtrack(g2, dc2, dp2, uf2)
            if result is not None:
                return result

        return None

    # Initialize
    uf = UnionFind(N1 * N1)

    result = backtrack(grid, dot_count, dot_possible, uf)

    if result is None:
        return "No Solution"

    return result

if __name__ == "__main__":
    print(solve(OBSERVATION))

