                        elif grid[cr][cc] == st:
                            cur_match += 1

                    needed = clue - cur_match
                    # unassigned_count doesn't include (r,c) since we're assigning it
                    remaining_unassigned = sum(1 for (cr, cc, st) in cells 
                                               if (cr, cc) != (r, c) and grid[cr][cc] is None)

                    if needed < 0:
                        return False
                    if needed > remaining_unassigned:
                        return False

        return True

    def backtrack(grid, uf):
        # Find first unassigned cell
        best_cell = None
        best_options = 3

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    options = []
                    for slash in ['/', '\\']:
                        if is_valid_assignment(grid, uf, r, c, slash):
                            options.append(slash)
                    if len(options) == 0:
                        return None
                    if len(options) < best_options:
                        best_options = len(options)
                        best_cell = (r, c, options)
                        if best_options == 1:
                            break
            if best_cell and best_options == 1:
                break

        if best_cell is None:
            # All assigned - check all dot constraints satisfied
            for dr in range(N+1):
                for dc in range(N+1):
                    clue = data[dr][dc]
                    if clue is None:
                        continue
                    cells = get_dot_cells(dr, dc)
                    count = sum(1 for (cr, cc, st) in cells if grid[cr][cc] == st)
                    if count != clue:
                        return None
            return grid

        r, c, options = best_cell

        for slash in options:
            # Deep copy
            new_grid = [row[:] for row in grid]
            new_uf = uf.copy()

            new_grid[r][c] = slash
            d1, d2 = cell_dots(r, c, slash)
            new_uf.union(dot_index(*d1), dot_index(*d2))

            # Propagate
            if propagate(new_grid, new_uf, {(r, c)}):
                result = backtrack(new_grid, new_uf)
                if result is not None:
                    return result

        return None

    # Initialize UF
    uf = UnionFind((N+1)*(N+1))

    # Initial propagation pass
    # Find cells forced by clue=0 dots or fully constrained dots
    changed = set()

    # Do initial constraint propagation
    dots_to_check = set()
    for dr in range(N+1):
        for dc in range(N+1):
            if data[dr][dc] is not None:
                dots_to_check.add((dr, dc))

    # Run propagation
    while dots_to_check:
        (dr, dc) = dots_to_check.pop()
        clue = data[dr][dc]
        if clue is None:
            continue

        cells = get_dot_cells(dr, dc)
        assigned_match = 0
        unassigned = []

        for (cr, cc, st) in cells:
            if grid[cr][cc] is None:
                unassigned.append((cr, cc, st))
            elif grid[cr][cc] == st:
                assigned_match += 1

        needed = clue - assigned_match
        available = len(unassigned)

        if needed < 0 or needed > available:
            return "No Solution"

        if needed == 0:
            for (cr, cc, st) in unassigned:
                other = '/' if st == '\\' else '\\'
                if grid[cr][cc] is None:
                    d1, d2 = cell_dots(cr, cc, other)
                    if uf.find(dot_index(*d1)) == uf.find(dot_index(*d2)):
                        return "No Solution"
                    grid[cr][cc] = other
                    uf.union(dot_index(*d1), dot_index(*d2))
                    for dr2 in [cr, cr+1]:
                        for dc2 in [cc, cc+1]:
                            if 0 <= dr2 <= N and 0 <= dc2 <= N:
                                if data[dr2][dc2] is not None:
                                    dots_to_check.add((dr2, dc2))

        elif needed == available:
            for (cr, cc, st) in unassigned:
                if grid[cr][cc] is None:
                    d1, d2 = cell_dots(cr, cc, st)
                    if uf.find(dot_index(*d1)) == uf.find(dot_index(*d2)):
                        return "No Solution"
                    grid[cr][cc] = st
                    uf.union(dot_index(*d1), dot_index(*d2))
                    for dr2 in [cr, cr+1]:
                        for dc2 in [cc, cc+1]:
                            if 0 <= dr2 <= N and 0 <= dc2 <= N:
                                if data[dr2][dc2] is not None:
                                    dots_to_check.add((dr2, dc2))

    result = backtrack(grid, uf)

    if result is None:
        return "No Solution"

    return result


