                    on_count = sum(1 for t,er,ec in cell_edges if get_edge(t,er,ec) == 1)
                    off_count = sum(1 for t,er,ec in cell_edges if get_edge(t,er,ec) == -1)
                    unknown = [(t,er,ec) for t,er,ec in cell_edges if get_edge(t,er,ec) == 0]

                    if on_count > clue:
