                    a, b = (r,c), (r+1,c)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)

        # Check for cycles using union-find
        parent = {}
        def find(x):
            if x not in parent:
                parent[x] = x
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False  # cycle detected
            parent[px] = py
            return True

        for r in range(R):
            for c in range(C-1):
                if h_edges[r][c] == 1:
                    a, b = (r,c), (r,c+1)
                    if not union(a, b):
