                        total_unk = sum(1 for rr in range(R) for cc in range(C-1) if h_edges[rr][cc]==0)
                        total_unk += sum(1 for rr in range(R-1) for cc in range(C) if v_edges[rr][cc]==0)
                        if total_unk > 0:
