        for r in range(R-1):
            for c in range(C):
                if v_edges[r][c] == 1:
                    a, b = (r,c), (r+1,c)
                    if not union(a, b):
                        total_unk = sum(1 for rr in range(R) for cc in range(C-1) if h_edges[rr][cc]==0)
                        total_unk += sum(1 for rr in range(R-1) for cc in range(C) if v_edges[rr][cc]==0)
                        if total_unk > 0:
                            return False
        return True

    def dfs():
        # Propagate first
        if not propagate():
            return False

        if not check_no_early_cycle():
            return False

        if is_complete():
            return is_valid_loop()

        # Find edge to branch on
        edge = find_unknown_edge()
        if edge is None:
            return is_valid_loop()

        t, er, ec = edge

        # Try ON
        state = save_state()
        set_edge(t, er, ec, 1)
        if dfs():
            return True
        restore_state(state)

        # Try OFF
        set_edge(t, er, ec, -1)
        if dfs():
            return True
        restore_state(state)

        return False

    if dfs():
        loop = extract_loop()
        if loop:
            return str(loop)

    return "No Solution"


