            if not next_nodes:
                break
            nxt = next_nodes[0]
            if nxt == start and len(path) > 2:
                path.append(start)
                return path
            if nxt in path:
                break
            path.append(nxt)
            prev = cur
            cur = nxt
        return None

    def backtrack():
        if not propagate():
            return False

        # Find first unknown edge
        best = None
        # Prefer edges adjacent to clue cells
        for r in range(rows):
            for c in range(cols):
                clue = data[r][c]
                if clue is None:
                    continue
                for t, er, ec in [('h', r, c), ('h', r+1, c), ('v', r, c), ('v', r, c+1)]:
                    if t == 'h' and h_edges[er][ec] == 0:
                        best = ('h', er, ec)
                        break
                    elif t == 'v' and v_edges[er][ec] == 0:
                        best = ('v', er, ec)
                        break
                if best:
                    break
            if best:
                break

        if best is None:
            # Try any unknown
            for r in range(R):
                for c in range(cols):
                    if h_edges[r][c] == 0:
                        best = ('h', r, c)
                        break
                if best:
