        # A cycle exists if any connected component has a cycle
        # For a valid partial state, ON edges should form paths (no cycles yet unless complete)

        # Check if there are unknown edges remaining
        has_unknown = any(h_edges[r][c] == 0 for r in range(R) for c in range(cols)) or \
                      any(v_edges[r][c] == 0 for r in range(rows) for c in range(C))

        if not has_unknown:
            return True  # Will be checked by is_valid_loop

        # Check for premature cycles: if ON edges form a cycle but there are still unknowns
        visited = set()
        for start in dot_adj:
            if start in visited:
                continue
            # DFS to detect cycle
            stack = [(start, None)]
            comp = set()
            has_cycle = False
            while stack:
                node, parent = stack.pop()
                if node in comp:
                    has_cycle = True
                    break
                comp.add(node)
                for nb in dot_adj.get(node, set()):
                    if nb != parent:
                        stack.append((nb, node))

            if has_cycle:
                return False
            visited |= comp

        return True

    def is_valid_loop():
        """Check if all ON edges form a single valid closed loop."""
        # Check all dots have degree 0 or 2
        for r in range(R):
            for c in range(C):
                edges = dot_edges(r, c)
                on = sum(1 for e in edges if edge_val(*e) == 1)
                if on not in (0, 2):
                    return False

        # Find ON edges
        on_dots = set()
        dot_adj = {}
        for r in range(R):
            for c in range(cols):
                if h_edges[r][c] == 1:
                    d1, d2 = (r, c), (r, c+1)
                    dot_adj.setdefault(d1, []).append(d2)
                    dot_adj.setdefault(d2, []).append(d1)
                    on_dots.add(d1); on_dots.add(d2)
        for r in range(rows):
            for c in range(C):
                if v_edges[r][c] == 1:
                    d1, d2 = (r, c), (r+1, c)
                    dot_adj.setdefault(d1, []).append(d2)
                    dot_adj.setdefault(d2, []).append(d1)
                    on_dots.add(d1); on_dots.add(d2)

        if not on_dots:
            return False

        # BFS from first dot
        start = min(on_dots)
        visited = set()
        queue = [start]
        while queue:
            node = queue.pop()
            if node in visited:
                continue
            visited.add(node)
            for nb in dot_adj.get(node, []):
                if nb not in visited:
                    queue.append(nb)

        return visited == on_dots

    def save_state():
        return ([row[:] for row in h_edges], [row[:] for row in v_edges])

    def restore_state(state):
        h, v = state
        for r in range(R):
            h_edges[r][:] = h[r]
        for r in range(rows):
            v_edges[r][:] = v[r]

    def find_best_unknown():
        """Find the best unknown edge to branch on (most constrained)."""
        # Score each unknown edge by how many clue cells it's adjacent to
        best_score = -1
        best_edge = None

        for r in range(R):
            for c in range(cols):
                if h_edges[r][c] == 0:
                    score = 0
                    if r > 0 and data[r-1][c] is not None: score += 1
                    if r < rows and data[r][c] is not None: score += 1
                    if score > best_score:
                        best_score = score
                        best_edge = ('h', r, c)

        for r in range(rows):
            for c in range(C):
                if v_edges[r][c] == 0:
                    score = 0
                    if c > 0 and data[r][c-1] is not None: score += 1
                    if c < cols and data[r][c] is not None: score += 1
                    if score > best_score:
                        best_score = score
                        best_edge = ('v', r, c)

        return best_edge

    def backtrack():
        if not propagate():
            return False

        if not check_no_premature_loop():
            return False

        # Check if all edges determined
        edge = find_best_unknown()

        if edge is None:
            return is_valid_loop()

        t, r, c = edge

        for val in [1, -1]:
            state = save_state()
            if t == 'h':
                h_edges[r][c] = val
            else:
                v_edges[r][c] = val

            if backtrack():
                return True

            restore_state(state)

        return False

    if not backtrack():
        return "No Solution"

    # Extract loop
    dot_adj = {}
    for r in range(R):
        for c in range(cols):
            if h_edges[r][c] == 1:
                d1, d2 = (r, c), (r, c+1)
                dot_adj.setdefault(d1, []).append(d2)
                dot_adj.setdefault(d2, []).append(d1)
    for r in range(rows):
        for c in range(C):
            if v_edges[r][c] == 1:
                d1, d2 = (r, c), (r+1, c)
                dot_adj.setdefault(d1, []).append(d2)
                dot_adj.setdefault(d2, []).append(d1)

    if not dot_adj:
        return "No Solution"

    start = min(dot_adj.keys())
    path = [start]
    prev = None
    cur = start

    while True:
        neighbors = [n for n in dot_adj.get(cur, []) if n != prev]
        if not neighbors:
            break
        nxt = neighbors[0]
        if nxt == start and len(path) > 2:
            path.append(start)
            break
        if nxt in path:
            break
        path.append(nxt)
        prev = cur
        cur = nxt

    return str(path)


