    # cells: rows x cols
    # h_edges[r][c]: horizontal edge between dot(r,c) and dot(r,c+1), r in 0..rows, c in 0..cols-1
    # v_edges[r][c]: vertical edge between dot(r,c) and dot(r+1,c), r in 0..rows-1, c in 0..cols

    num_rows = rows + 1  # dot rows
    num_cols = cols + 1  # dot cols

    # Edge states: 0=no, 1=yes, -1=unknown
    # h_edges: (num_rows) x (cols) 
    # v_edges: (rows) x (num_cols)

