        # Returns (top_h, bottom_h, left_v, right_v)
        # top: h_edges[r][c]
        # bottom: h_edges[r+1][c]
        # left: v_edges[r][c]
        # right: v_edges[r][c+1]
        return (h_edges[r][c], h_edges[r+1][c], v_edges[r][c], v_edges[r][c+1])

    def count_cell_edges(r, c):
        edges = get_cell_edges(r, c)
        yes = sum(1 for e in edges if e == 1)
        no = sum(1 for e in edges if e == 0)
        unk = sum(1 for e in edges if e == -1)
        return yes, no, unk

    def get_dot_edges(r, c):
        # Returns list of (edge_type, er, ec) for edges at dot (r,c)
        result = []
        # top h_edge: h_edges[r][c-1] if c>0
        if c > 0:
            result.append(('h', r, c-1))
        # right h_edge: h_edges[r][c] if c<W
        if c < W:
            result.append(('h', r, c))
        # top v_edge: v_edges[r-1][c] if r>0
        if r > 0:
            result.append(('v', r-1, c))
        # bottom v_edge: v_edges[r][c] if r<VH
        if r < VH:
            result.append(('v', r, c))
        return result

    def get_edge_val(etype, er, ec):
        if etype == 'h':
            return h_edges[er][ec]
        else:
            return v_edges[er][ec]

    def set_edge(etype, er, ec, val):
        if etype == 'h':
            if h_edges[er][ec] != -1 and h_edges[er][ec] != val:
                return False
            h_edges[er][ec] = val
        else:
            if v_edges[er][ec] != -1 and v_edges[er][ec] != val:
                return False
            v_edges[er][ec] = val
        return True

    def copy_state():
        return ([row[:] for row in h_edges], [row[:] for row in v_edges])

    def restore_state(state):
        nonlocal h_edges, v_edges
        h_edges, v_edges = state

    # Propagation queue
    def propagate():
        changed = True
        while changed:
            changed = False
            # Check cell constraints
            for r in range(rows):
                for c in range(cols):
