                            if get_edge_val(etype, er, ec) == -1:
                                if not set_edge(etype, er, ec, 0):
                                    return False
                                changed = True
                    # If yes + unk == clue, set all unknown to 1
                    if yes + unk == clue:
                        cell_edges = [
                            ('h', r, c), ('h', r+1, c),
                            ('v', r, c), ('v', r, c+1)
                        ]
                        for etype, er, ec in cell_edges:
                            if get_edge_val(etype, er, ec) == -1:
                                if not set_edge(etype, er, ec, 1):
                                    return False
                                changed = True

