                    yes = sum(1 for et, er, ec in dot_edges if get_edge_val(et, er, ec) == 1)
                    no = sum(1 for et, er, ec in dot_edges if get_edge_val(et, er, ec) == 0)
                    unk = sum(1 for et, er, ec in dot_edges if get_edge_val(et, er, ec) == -1)
                    total = len(dot_edges)

