                            if get_edge_val(et, er, ec) == -1:
                                if not set_edge(et, er, ec, 0):
                                    return False
                                changed = True
                    if yes == 1 and unk == 1:
                        # Must complete to 2
                        for et, er, ec in dot_edges:
                            if get_edge_val(et, er, ec) == -1:
                                if not set_edge(et, er, ec, 1):
                                    return False
                                changed = True
