        for r in range(H):
            for c in range(W):
                if h_edges[r][c] == -1:
                    return False
        for r in range(VH):
            for c in range(VW):
                if v_edges[r][c] == -1:
                    return False
        return True

    def is_valid_loop():
        # Check all dots have 0 or 2 active edges
        for r in range(num_rows):
            for c in range(num_cols):
                dot_edges = get_dot_edges(r, c)
                yes = sum(1 for et, er, ec in dot_edges if get_edge_val(et, er, ec) == 1)
                if yes not in (0, 2):
                    return False

        # Check single connected loop
        # Find all active edges and check connectivity
        active_dots = set()
        adj = defaultdict(set)

        for r in range(H):
            for c in range(W):
