            for c in range(VW):
                if v_edges[r][c] == 1:
                    d1 = (r, c)
                    d2 = (r+1, c)
                    active_dots.add(d1)
                    active_dots.add(d2)
                    adj[d1].add(d2)
                    adj[d2].add(d1)

        if not active_dots:
            return False

        # BFS from one dot
        start = next(iter(active_dots))
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            node = queue.pop()
            for nb in adj[node]:
                if nb not in visited:
                    visited.add(nb)
                    queue.append(nb)

        return visited == active_dots

    def extract_loop():
        # Build adjacency
        adj = defaultdict(list)
        for r in range(H):
            for c in range(W):
                if h_edges[r][c] == 1:
                    d1 = (r, c)
                    d2 = (r, c+1)
                    adj[d1].append(d2)
                    adj[d2].append(d1)
        for r in range(VH):
            for c in range(VW):
                if v_edges[r][c] == 1:
                    d1 = (r, c)
                    d2 = (r+1, c)
                    adj[d1].append(d2)
                    adj[d2].append(d1)

