        start = None
        for r in range(num_rows):
            for c in range(num_cols):
                if len(adj[(r,c)]) == 2:
                    start = (r, c)
                    break
            if start:
                break

        if not start:
            return None

        path = [start]
        prev = None
        cur = start
        while True:
            neighbors = adj[cur]
            nxt = None
            for nb in neighbors:
                if nb != prev:
