        for r in range(VH):
            for c in range(VW):
                if v_edges[r][c] == 1:
                    d1 = (r, c)
                    d2 = (r+1, c)
                    active_dots.add(d1)
                    active_dots.add(d2)
                    adj[d1].append(d2)
                    adj[d2].append(d1)

        if not active_dots:
