        if best is None:
            # Find any unknown edge
            for r in range(H):
                for c in range(W):
                    if h_edges[r][c] == -1:
                        best = ('h', r, c)
                        break
                if best:
                    break
            if best is None:
                for r in range(VH):
                    for c in range(VW):
                        if v_edges[r][c] == -1:
                            best = ('v', r, c)
                            break
                    if best:
                        break

        if best is None:
            return is_valid_loop()

        etype, er, ec = best

        # Try both values
        for val in [1, 0]:
            state = copy_state()
            if set_edge(etype, er, ec, val):
                if backtrack():
                    return True
            restore_state(state)

        return False

    if backtrack():
        loop = extract_loop()
        if loop:
            return str(loop)

    return "No Solution"


