                    total_unk = sum(1 for r in range(H) for c in range(W) if h_edges[r][c] == -1)
                    total_unk += sum(1 for r in range(VH) for c in range(VW) if v_edges[r][c] == -1)
                    if total_unk > 0:
                        return False  # premature cycle
                comp += 1
        return True

    def backtrack():
        # Propagate first
        if not propagate():
            return False

        if not check_no_premature_loop():
            return False

        if is_complete():
            return is_valid_loop()

        # Find an unknown edge to branch on
        # Prefer edges adjacent to cells with clues
        best = None
        best_score = -1

        # Try to find most constrained edge
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is not None:
                    cell_edges = [
                        ('h', r, c), ('h', r+1, c),
                        ('v', r, c), ('v', r, c+1)
                    ]
                    for etype, er, ec in cell_edges:
                        if get_edge_val(etype, er, ec) == -1:
                            yes, no, unk = count_cell_edges(r, c)
                            score = 4 - unk  # more constrained = higher score
                            if score > best_score:
                                best_score = score
                                best = (etype, er, ec)

        if best is None:
            # Find any unknown edge
            for r in range(H):
                for c in range(W):
                    if h_edges[r][c] == -1:
                        best = ('h', r, c)
                        break
                if best:
                    break
            if best is None:
                for r in range(VH):
                    for c in range(VW):
                        if v_edges[r][c] == -1:
                            best = ('v', r, c)
                            break
                    if best:
                        break

        if best is None:
            return is_valid_loop()

        etype, er, ec = best

        # Try both values
        for val in [1, 0]:
            state = copy_state()
            if set_edge(etype, er, ec, val):
                if backtrack():
                    return True
            restore_state(state)

        return False

    if backtrack():
        loop = extract_loop()
        if loop:
            return str(loop)

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))
