# Now implement the Slitherlink solver
# Grid: N rows, M cols of cells (clues)
# Dots: (N+1) x (M+1)
# Edges: horizontal edges between (r,c)-(r,c+1) and vertical edges between (r,c)-(r+1,c)

from collections import defaultdict

def solve(observation):
    data = observation['data']
    N = len(data)
    M = len(data[0])

    # Edge representation:
    # H[r][c] = horizontal edge between dot(r,c) and dot(r,c+1), r in 0..N, c in 0..M-1
    # V[r][c] = vertical edge between dot(r,c) and dot(r+1,c), r in 0..N-1, c in 0..M

    # State: 0=off, 1=on, -1=unknown
    H = [[0] * M for _ in range(N+1)]  # will use None for unknown
    V = [[0] * (M+1) for _ in range(N)]

    # Use None=unknown, True=on, False=off
    H = [[None]*M for _ in range(N+1)]
    V = [[None]*(M+1) for _ in range(N)]

    def get_cell_edges(r, c):
        # Returns (top, bottom, left, right) edge references as (type, r, c)
        # top: H[r][c], bottom: H[r+1][c], left: V[r][c], right: V[r][c+1]
        return [('H', r, c), ('H', r+1, c), ('V', r, c), ('V', r, c+1)]

    def get_edge(t, r, c):
        if t == 'H':
            return H[r][c]
        else:
            return V[r][c]

    def set_edge(t, r, c, val):
        if t == 'H':
            H[r][c] = val
        else:
            V[r][c] = val

    def get_dot_edges(r, c):
        # Returns edges incident to dot (r,c)
        edges = []
        if c > 0: edges.append(('H', r, c-1))
        if c < M: edges.append(('H', r, c))
        if r > 0: edges.append(('V', r-1, c))
        if r < N: edges.append(('V', r, c))
        return edges

    # Constraint propagation
    changed = True

    def propagate():
        nonlocal changed
        changed = True
        while changed:
            changed = False
            # Cell constraints
            for r in range(N):
                for c in range(M):
                    clue = data[r][c]
                    if clue is None:
                        continue
                    edges = get_cell_edges(r, c)
                    on_count = sum(1 for e in edges if get_edge(*e) == True)
                    off_count = sum(1 for e in edges if get_edge(*e) == False)
                    unknown = [e for e in edges if get_edge(*e) is None]

                    if on_count > clue:
                        return False
                    if off_count > 4 - clue:
                        return False

                    if on_count == clue:
                        for e in unknown:
                            set_edge(*e, False)
                            changed = True
                    if len(unknown) == clue - on_count:
                        for e in unknown:
                            set_edge(*e, True)
                            changed = True

            # Dot constraints: each dot must have 0 or 2 active edges
            for r in range(N+1):
                for c in range(M+1):
                    edges = get_dot_edges(r, c)
                    on_edges = [e for e in edges if get_edge(*e) == True]
                    off_edges = [e for e in edges if get_edge(*e) == False]
                    unknown_edges = [e for e in edges if get_edge(*e) is None]

                    on = len(on_edges)

                    if on > 2:
                        return False
                    if on == 2:
                        for e in unknown_edges:
                            set_edge(*e, False)
                            changed = True
                    if on == 1 and len(unknown_edges) == 0:
                        return False  # dead end
                    if on == 1 and len(unknown_edges) == 1:
                        # Must turn on the unknown
                        set_edge(*unknown_edges[0], True)
                        changed = True
                    # If on==0 and only 1 unknown: must be off (can't have degree 1)
                    # Actually if on==0 and 1 unknown, that unknown must be off
                    if on == 0 and len(unknown_edges) == 1:
                        set_edge(*unknown_edges[0], False)
                        changed = True
        return True

    def check_solution():
        # Check all clues satisfied
        for r in range(N):
            for c in range(M):
                clue = data[r][c]
                if clue is None:
                    continue
                edges = get_cell_edges(r, c)
                on_count = sum(1 for e in edges if get_edge(*e) == True)
                if on_count != clue:
                    return False

        # Check all dots have degree 0 or 2
        for r in range(N+1):
            for c in range(M+1):
                edges = get_dot_edges(r, c)
                on = sum(1 for e in edges if get_edge(*e) == True)
                if on not in (0, 2):
                    return False

        # Check single loop
        # Find all on-edges
        on_edges = []
        for r in range(N+1):
            for c in range(M):
                if H[r][c] == True:
                    on_edges.append(('H', r, c))
        for r in range(N):
            for c in range(M+1):
                if V[r][c] == True:
                    on_edges.append(('V', r, c))

        if not on_edges:
            return False

        # Build adjacency
        adj = defaultdict(list)
        for e in on_edges:
            t, r, c = e
            if t == 'H':
                d1, d2 = (r, c), (r, c+1)
            else:
                d1, d2 = (r, c), (r+1, c)
            adj[d1].append(d2)
            adj[d2].append(d1)

        # BFS/DFS to check connectivity
        start = next(iter(adj))
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for nb in adj[node]:
                if nb not in visited:
                    stack.append(nb)

        return len(visited) == len(adj)

    def extract_loop():
        # Extract the loop as ordered list of dot coordinates
        adj = defaultdict(list)
        for r in range(N+1):
            for c in range(M):
                if H[r][c] == True:
                    adj[(r,c)].append((r,c+1))
                    adj[(r,c+1)].append((r,c))
        for r in range(N):
            for c in range(M+1):
                if V[r][c] == True:
                    adj[(r,c)].append((r+1,c))
                    adj[(r+1,c)].append((r,c))

        if not adj:
            return None

        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start
        while True:
            neighbors = adj[cur]
            next_node = None
            for nb in neighbors:
                if nb != prev:
                    next_node = nb
                    break
            if next_node is None:
                break
            if next_node == start:
                path.append(start)
                break
            path.append(next_node)
            prev = cur
            cur = next_node

        return path

    def save_state():
        return ([row[:] for row in H], [row[:] for row in V])

    def restore_state(state):
        nonlocal H, V
        sh, sv = state
        for r in range(N+1):
            H[r] = sh[r][:]
        for r in range(N):
            V[r] = sv[r][:]

    def find_unknown():
        for r in range(N+1):
            for c in range(M):
                if H[r][c] is None:
                    return ('H', r, c)
        for r in range(N):
            for c in range(M+1):
                if V[r][c] is None:
                    return ('V', r, c)
        return None

    def check_partial():
        # Quick validity check without full solution check
        for r in range(N):
            for c in range(M):
                clue = data[r][c]
                if clue is None:
                    continue
                edges = get_cell_edges(r, c)
                on_count = sum(1 for e in edges if get_edge(*e) == True)
                off_count = sum(1 for e in edges if get_edge(*e) == False)
                if on_count > clue:
                    return False
                if off_count > 4 - clue:
                    return False

        for r in range(N+1):
            for c in range(M+1):
                edges = get_dot_edges(r, c)
                on = sum(1 for e in edges if get_edge(*e) == True)
                if on > 2:
                    return False

        return True

    def check_no_premature_loop():
        """Check that on-edges don't form a closed loop unless all edges are determined"""
        # Build graph of on-edges
        adj = defaultdict(set)
        for r in range(N+1):
            for c in range(M):
                if H[r][c] == True:
                    adj[(r,c)].add((r,c+1))
                    adj[(r,c+1)].add((r,c))
        for r in range(N):
            for c in range(M+1):
                if V[r][c] == True:
                    adj[(r,c)].add((r+1,c))
                    adj[(r+1,c)].add((r,c))

        # Check for any cycle in on-edges
        # If there's a cycle and there are still unknown edges, it's invalid
        # (unless the cycle IS the complete loop)

        # Count unknown edges
        unknown_count = sum(1 for r in range(N+1) for c in range(M) if H[r][c] is None)
        unknown_count += sum(1 for r in range(N) for c in range(M+1) if V[r][c] is None)

        if unknown_count > 0:
            # Check if on-edges form any cycle
            visited = set()
            for start in list(adj.keys()):
                if start in visited:
                    continue
                # DFS
                stack = [(start, None)]
                comp = set()
                has_cycle = False
                while stack:
                    node, parent = stack.pop()
                    if node in comp:
                        has_cycle = True
                        break
                    comp.add(node)
                    for nb in adj[node]:
                        if nb != parent:
                            stack.append((nb, node))
                if has_cycle:
                    return False
                visited |= comp

        return True

    def dfs():
        if not propagate():
            return False

        if not check_partial():
            return False

        if not check_no_premature_loop():
            return False

        unknown = find_unknown()
        if unknown is None:
            return check_solution()

        t, r, c = unknown

        for val in [True, False]:
            state = save_state()
            set_edge(t, r, c, val)
            if dfs():
                return True
            restore_state(state)

        return False

    # Apply initial propagation with special rules
    # Rule: 0-clue cells have all edges off
    for r in range(N):
        for c in range(M):
            if data[r][c] == 0:
                for e in get_cell_edges(r, c):
                    set_edge(*e, False)

    # Rule: 3-clue corner cells
    # Corner (0,0): top=H[0][0], left=V[0][0] - these are border edges
    # For a 3-clue at corner, at least 2 of the 2 border edges must be on
    # Actually for corner cell with clue 3: only 2 edges are "real" (non-border don't exist)
    # Wait, all 4 edges exist (top, bottom, left, right)
    # Corner cell (0,0): top=H[0][0], bottom=H[1][0], left=V[0][0], right=V[0][1]

    if dfs():
        loop = extract_loop()
        if loop:
            return str(loop)

    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

