        for r in range(R-1):
            for c in range(C):
                if v[r][c] == 1:
                    a, b = (r, c), (r+1, c)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)
        if not adj:
            return None
        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start
        while True:
            nbs = adj[cur]
            nxt = None
            for nb in nbs:
                if nb != prev:
                    nxt = nb
                    break
            if nxt is None:
                break
            if nxt == start:
                path.append(start)
                break
            path.append(nxt)
            prev, cur = cur, nxt
        return path

    # Check loop connectivity during search (partial)
    def check_no_premature_loop(state):
        """Check that on-edges don't form a closed loop prematurely (unless all edges determined)"""
        h, v = state
        adj = {}
        for r in range(R):
            for c in range(C-1):
                if h[r][c] == 1:
                    a, b = (r, c), (r, c+1)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)
        for r in range(R-1):
            for c in range(C):
                if v[r][c] == 1:
                    a, b = (r, c), (r+1, c)
                    adj.setdefault(a, []).append(b)
                    adj.setdefault(b, []).append(a)
        if not adj:
            return True
        # Check for cycles using DFS
        visited = {}
        def has_cycle(node, parent):
            visited[node] = True
            for nb in adj.get(node, []):
                if nb not in visited:
                    if has_cycle(nb, node):
                        return True
                elif nb != parent:
                    return True
            return False
        # Check each component
        for start in list(adj.keys()):
            if start not in visited:
                if has_cycle(start, None):
                    # Found a cycle - check if it's the complete loop
                    # Count on edges
                    on_edges = sum(1 for r in range(R) for c in range(C-1) if h[r][c]==1)
                    on_edges += sum(1 for r in range(R-1) for c in range(C) if v[r][c]==1)
                    # Check if all unknowns are gone
                    has_unknown = any(h[r][c]==0 for r in range(R) for c in range(C-1))
                    has_unknown = has_unknown or any(v[r][c]==0 for r in range(R-1) for c in range(C))
                    if has_unknown:
                        return False  # premature cycle
        return True

    # Get next undecided edge for branching
    def get_next_edge(state):
        h, v = state
        # Prefer edges adjacent to clue cells
        for r in range(rows):
            for c in range(cols):
                if data[r][c] is not None:
                    for et, er, ec in cell_edges(r, c):
                        if get_edge(state, et, er, ec) == 0:
                            return (et, er, ec)
        # Then any edge
        for r in range(R):
            for c in range(C-1):
                if h[r][c] == 0:
                    return ('h', r, c)
        for r in range(R-1):
            for c in range(C):
                if v[r][c] == 0:
                    return ('v', r, c)
        return None

    def backtrack(state):
        # Propagate first
        # Find next undecided edge
        edge = get_next_edge(state)
        if edge is None:
            # All edges decided
            if check_solution(state):
                return state
            return None

        et, er, ec = edge
        for val in [1, -1]:
            new_state = copy_state(state)
            set_edge(new_state, et, er, ec, val)
            queue = [(et, er, ec)]
            if propagate(new_state, queue):
                if check_no_premature_loop(new_state):
                    result = backtrack(new_state)
                    if result is not None:
                        return result
        return None

    # Initialize
    state = make_state()
    # Initial propagation from clues
    queue = []
    # Force 0-clue cells
    for r in range(rows):
        for c in range(cols):
            clue = data[r][c]
            if clue == 0:
                for et, er, ec in cell_edges(r, c):
                    set_edge(state, et, er, ec, -1)
                    queue.append((et, er, ec))
            elif clue == 4:
                for et, er, ec in cell_edges(r, c):
                    set_edge(state, et, er, ec, 1)
                    queue.append((et, er, ec))

    if not propagate(state, queue):
        return "No Solution"

    result = backtrack(state)
    if result is None:
        return "No Solution"

    loop = extract_loop(result)
    if loop is None:
        return "No Solution"
    return str(loop)


