# Star Battle Solver - 1 star per row, col, region
# Uses constraint propagation + backtracking with aggressive pruning

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Find all regions
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = grid[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    num_regions = len(regions)

    # We need exactly 1 star per row, col, region
    # stars[r] = col of star in row r, or -1 if not placed

    # Precompute: for each region, list of cells
    region_list = [regions[i] for i in sorted(regions.keys())]

    # State: 
    # - stars: list of length N, stars[r] = col or -1
    # - used_cols: set of used columns
    # - used_regions: set of used region ids
    # - forbidden: set of (r,c) that cannot have stars (adjacency)

    def get_region(r, c):
        return grid[r][c]

    def is_adjacent_to_any_star(r, c, star_positions):
        # Check if (r,c) is adjacent (including diagonal) to any placed star
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if star_positions.get(nr) == nc:
                        return True
        return False

    # Human-like solving: process rows in order
    # For each row, try each column that is:
    # 1. Not used by another row's star
    # 2. Not in a region already used
    # 3. Not adjacent to any existing star

    # Forward checking: after placing a star, check if remaining rows/cols/regions
    # still have valid candidates

    def get_candidates(row, used_cols, used_regions, star_positions):
        candidates = []
        for c in range(N):
            if c in used_cols:
                continue
            rid = get_region(row, c)
            if rid in used_regions:
                continue
            if is_adjacent_to_any_star(row, c, star_positions):
                continue
            candidates.append(c)
        return candidates

    def forward_check(row, used_cols, used_regions, star_positions):
        # Check all unassigned rows have at least one valid candidate
        for r in range(row + 1, N):
            if star_positions.get(r, -1) != -1:
                continue
            cands = get_candidates(r, used_cols, used_regions, star_positions)
            if not cands:
                return False

        # Check all unused regions have at least one valid cell in an unassigned row
        for rid in range(num_regions):
            if rid in used_regions:
                continue
            # Find if any cell in this region is in an unassigned row with valid placement
            has_valid = False
            for (r, c) in region_list[rid]:
                if star_positions.get(r, -1) != -1:
                    continue  # row already assigned
                if c in used_cols:
                    continue
                if is_adjacent_to_any_star(r, c, star_positions):
                    continue
                has_valid = True
                break
            if not has_valid:
                return False

        # Check all unused columns have at least one valid cell in an unassigned row
        for col in range(N):
            if col in used_cols:
                continue
            has_valid = False
            for r in range(N):
                if star_positions.get(r, -1) != -1:
                    continue
                rid = get_region(r, col)
                if rid in used_regions:
                    continue
                if is_adjacent_to_any_star(r, col, star_positions):
                    continue
                has_valid = True
                break
            if not has_valid:
                return False

        return True

    def backtrack(row, used_cols, used_regions, star_positions):
        if row == N:
            # Check all regions covered
            if len(used_regions) == num_regions:
                return dict(star_positions)
            return None

        candidates = get_candidates(row, used_cols, used_regions, star_positions)

        for c in candidates:
            rid = get_region(row, c)
            star_positions[row] = c
            used_cols.add(c)
            used_regions.add(rid)

            if forward_check(row, used_cols, used_regions, star_positions):
                result = backtrack(row + 1, used_cols, used_regions, star_positions)
                if result is not None:
                    return result

            del star_positions[row]
            used_cols.remove(c)
            used_regions.remove(rid)

        return None

    result = backtrack(0, set(), set(), {})

    if result is None:
        return "No Solution"

    # Build output grid
    output = [[None] * N for _ in range(N)]
    for r, c in result.items():
        output[r][c] = 'S'

    return output


