                if rid in used_regions:
                    continue
                if is_adjacent_to_any_star(r, col, star_positions):
                    continue
                has_valid = True
                break
            if not has_valid:
                return False

        return True

    def backtrack(row, used_cols, used_regions, star_positions):
        if row == N:
            # Check all regions covered
            if len(used_regions) == num_regions:
                return dict(star_positions)
            return None

        candidates = get_candidates(row, used_cols, used_regions, star_positions)

