# Human-like constraint propagation + backtracking solver for Star Battle (1-star variant)
# Rules:
# 1. Each row has exactly 1 star
# 2. Each column has exactly 1 star
# 3. Stars cannot touch each other (including diagonally)
# 4. Black cells cannot have stars

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Precompute valid columns for each row (non-black cells)
    row_candidates = []
    for r in range(N):
        candidates = [c for c in range(N) if grid[r][c] != 'B']
        row_candidates.append(candidates)

    # Check if placing a star at (r, c) conflicts with already placed stars
    def conflicts(r, c, placed):
        # placed is a dict: row -> col
        for pr, pc in placed.items():
            # Same column
            if pc == c:
                return True
            # Diagonal adjacency
            if abs(pr - r) <= 1 and abs(pc - c) <= 1:
                return True
        return False

    # Forward checking: for each unassigned row, compute remaining valid columns
    def forward_check(placed, remaining_rows):
        # Returns pruned candidates dict or None if any row has no candidates
        pruned = {}
        for r in remaining_rows:
            valid = []
            for c in row_candidates[r]:
                if c not in [placed[pr] for pr in placed]:  # column not used
                    if not conflicts(r, c, placed):
                        valid.append(c)
            if not valid:
                return None
            pruned[r] = valid
        return pruned

    # Use MRV (Minimum Remaining Values) heuristic to pick next row
    def pick_row(pruned_candidates):
        min_count = float('inf')
        chosen = None
        for r, cands in pruned_candidates.items():
            if len(cands) < min_count:
                min_count = len(cands)
                chosen = r
        return chosen

    # Backtracking search with constraint propagation
    def backtrack(placed, pruned_candidates):
        if len(placed) == N:
            return placed

        # Pick row with fewest candidates (MRV)
        r = pick_row(pruned_candidates)
        if r is None:
            return None

        candidates = pruned_candidates[r]

        for c in candidates:
            # Check column not already used
            used_cols = set(placed.values())
            if c in used_cols:
                continue

            # Check no conflict with placed stars
            if conflicts(r, c, placed):
                continue

            # Place star
            new_placed = dict(placed)
            new_placed[r] = c

            # Remaining rows
            remaining = {row: cands for row, cands in pruned_candidates.items() if row != r}

            # Forward check
            new_pruned = {}
            feasible = True
            for row, cands in remaining.items():
                valid = []
                for col in cands:
                    if col == c:  # column taken
                        continue
                    if not conflicts(row, col, new_placed):
                        valid.append(col)
                if not valid:
                    feasible = False
                    break
                new_pruned[row] = valid

            if not feasible:
                continue

            result = backtrack(new_placed, new_pruned)
            if result is not None:
                return result

        return None

    # Initialize candidates
    initial_candidates = {}
    for r in range(N):
        cands = row_candidates[r]
        if not cands:
            return "No Solution"
        initial_candidates[r] = cands

    result = backtrack({}, initial_candidates)

    if result is None:
        return "No Solution"

    # Build answer grid
    answer = [[None] * N for _ in range(N)]
    for r, c in result.items():
        answer[r][c] = 'S'

    return answer

