                for fc in row_candidates[future_row]:
                    if fc in used_cols:
                        continue
                    # Check adjacency with all placed stars
                    adj = False
                    for pr, pc in last_placements:
                        if is_adjacent(future_row, fc, pr, pc):
                            adj = True
                            break
                    if not adj:
                        has_valid = True
                        break
                if not has_valid:
                    feasible = False
                    break

            if feasible:
                result = backtrack(row + 1, used_cols, placement, last_placements)
                if result is not None:
                    return result

            used_cols.remove(col)
            placement[row] = -1
            last_placements.pop()

        return None

    placement = [-1] * N
    result = backtrack(0, set(), placement, [])

    if result is None:
        return "No Solution"

    # Build answer grid
    answer = [[None] * N for _ in range(N)]
    for r in range(N):
        answer[r][result[r]] = 'S'

