        box_rows, box_cols = int(parts[0]), int(parts[1])
    else:
        box_rows = box_cols = int(unit_str)

    N = box_rows * box_cols
    values = set(range(1, N + 1))

    # Initialize grid
    grid = []
    for row in data:
        grid.append([cell for cell in row])

    # Precompute box index for each cell
    def get_box(r, c):
        return (r // box_rows) * (N // box_cols) + (c // box_cols)

    num_boxes = (N // box_rows) * (N // box_cols)

    # Initialize constraint sets: used values in each row, col, box
    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    box_used = [set() for _ in range(num_boxes)]

    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v is not None:
                row_used[r].add(v)
                col_used[c].add(v)
                box_used[get_box(r, c)].add(v)

    # Candidates for each cell
    def get_candidates(r, c):
        if grid[r][c] is not None:
            return set()
        b = get_box(r, c)
        return values - row_used[r] - col_used[c] - box_used[b]

    # Build candidates dict for empty cells
    candidates = {}
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                cands = get_candidates(r, c)
                if not cands:
                    return "No Solution"
                candidates[(r, c)] = cands

    def assign(r, c, v):
        grid[r][c] = v
        row_used[r].add(v)
        col_used[c].add(v)
        box_used[get_box(r, c)].add(v)
        if (r, c) in candidates:
            del candidates[(r, c)]

    def unassign(r, c, v):
        grid[r][c] = None
        row_used[r].discard(v)
        col_used[c].discard(v)
        box_used[get_box(r, c)].discard(v)
        candidates[(r, c)] = get_candidates(r, c)

    # Naked singles propagation
    def propagate():
        changed = True
        while changed:
            changed = False
            # Naked singles
            for (r, c) in list(candidates.keys()):
                cands = get_candidates(r, c)
                if not cands:
                    return False
                if len(cands) == 1:
                    v = next(iter(cands))
                    assign(r, c, v)
