    # Save and restore state for backtracking
    def save_state():
        g = [row[:] for row in grid]
        ru = [s.copy() for s in row_used]
        cu = [s.copy() for s in col_used]
        bu = [s.copy() for s in box_used]
        cands = {k: v.copy() for k, v in candidates.items()}
        return g, ru, cu, bu, cands

    def restore_state(state):
