# Human-like constraint propagation + backtracking solver for Tent puzzle

def solve(observation):
    tree_grid = observation['tree']
    row_counts = observation['row_tent_counts']
    col_counts = observation['col_tent_counts']

    R = len(tree_grid)
    C = len(tree_grid[0]) if R > 0 else 0

    # Find all tree positions
    trees = []
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))

    N = len(trees)  # number of trees = number of tents

    # For each tree, compute candidate tent positions (orthogonal neighbors that are not trees)
    def get_neighbors(r, c):
        result = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and tree_grid[nr][nc] != 'T':
                result.append((nr, nc))
        return result

    tree_candidates = []
    for (tr, tc) in trees:
        cands = get_neighbors(tr, tc)
        tree_candidates.append(cands)

    # State: assignment[i] = (r,c) tent position for tree i, or None
    # We use backtracking with constraint propagation

    # Check no two tents are adjacent (including diagonal)
    def tents_conflict(r1, c1, r2, c2):
        return abs(r1-r2) <= 1 and abs(c1-c2) <= 1

    # Count tents placed so far per row/col
    # We'll use a set of placed tent positions

    best_solution = [None]

    def backtrack(idx, placed_tents, row_used, col_used, tree_paired):
        # placed_tents: set of (r,c) tent positions placed so far
        # row_used[r]: count of tents in row r
        # col_used[c]: count of tents in col c
        # tree_paired: set of tree indices that have been assigned

        if idx == N:
            # Check all row/col counts satisfied
            for r in range(R):
                if row_used[r] != row_counts[r]:
                    return
            for c in range(C):
                if col_used[c] != col_counts[c]:
                    return
            # Found solution
            grid = [[None]*C for _ in range(R)]
            for (r,c) in placed_tents:
                grid[r][c] = 't'
            best_solution[0] = grid
            return

        if best_solution[0] is not None:
            return

        # Pruning: check if remaining row/col counts can still be satisfied
        # For rows: tents placed so far + remaining trees can't exceed row_counts
        # Quick feasibility check
        for r in range(R):
            if row_used[r] > row_counts[r]:
                return
        for c in range(C):
            if col_used[c] > col_counts[c]:
                return

        # Try each candidate for tree idx
        candidates = tree_candidates[idx]

        # Filter candidates: not already used as tent, not conflicting with existing tents
        valid_cands = []
        for (r, c) in candidates:
            if (r, c) in placed_tents:
                continue
            # Check no conflict with existing tents
            conflict = False
            for (pr, pc) in placed_tents:
                if tents_conflict(r, c, pr, pc):
                    conflict = True
                    break
            if conflict:
                continue
            # Check row/col counts not exceeded
            if row_used[r] + 1 > row_counts[r]:
                continue
            if col_used[c] + 1 > col_counts[c]:
                continue
            valid_cands.append((r, c))

        if not valid_cands:
            return

        # Order candidates: prefer those in rows/cols with tighter constraints
        def cand_priority(rc):
            r, c = rc
            # Remaining capacity
            row_rem = row_counts[r] - row_used[r]
            col_rem = col_counts[c] - col_used[c]
            return (row_rem + col_rem)

        valid_cands.sort(key=cand_priority)

        for (r, c) in valid_cands:
            if best_solution[0] is not None:
                return
            placed_tents.add((r, c))
            row_used[r] += 1
            col_used[c] += 1

            backtrack(idx+1, placed_tents, row_used, col_used, tree_paired)

