    def is_valid_partial(g):
        # Check no 2x2 block is all same color (only for fully filled blocks)
        for r in range(N-1):
            for c in range(N-1):
                cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
                if all(x == 'B' for x in cells) or all(x == 'W' for x in cells):
                    return False
        return True

    def check_connectivity(g, color):
        # Find all cells of given color
        cells = [(r,c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells:
            return True
        # BFS from first cell
        visited = set()
        queue = deque([cells[0]])
        visited.add(cells[0])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < N and 0 <= nc < N and (nr,nc) not in visited and g[nr][nc] == color:
                    visited.add((nr,nc))
                    queue.append((nr,nc))
        return len(visited) == len(cells)

    def can_still_connect(g, color):
        # Check if it's still possible for all cells of 'color' to be connected
        # considering None cells as potential color cells
        cells = [(r,c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells:
            return True
        # potential cells: color or None
        potential = set((r,c) for r in range(N) for c in range(N) if g[r][c] == color or g[r][c] is None)
        # BFS from first color cell through potential cells
        visited = set()
        queue = deque([cells[0]])
        visited.add(cells[0])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr,nc) in potential and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))
        # All color cells must be reachable
        return all(cell in visited for cell in cells)

