            return True
        visited = set()
        queue = deque([cells[0]])
        visited.add(cells[0])
        while queue:
            r, c = queue.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == color:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
